      const taper = 0.56 + 0.44 * ((y + 0.56) / 1.12);
      capePos.setX(i, capePos.getX(i) * taper);
      if (y < -0.42) capePos.setX(i, capePos.getX(i) + Math.sin(y * 9) * 0.025);
    }
