      for (let i = 0; i < 7; i++) {
        const a = (i / 7) * Math.PI * 2;
        addCone(crown, 0.075, 0.45 + (i % 2) * 0.25, trim, Math.cos(a) * 0.32, 0.2, Math.sin(a) * 0.32, 0, 0, Math.cos(a) * 0.3);
      }
      const crackMat = new THREE.MeshBasicMaterial({ color: 0xff5b22 });
      for (let i = 0; i < 5; i++) {
        const crack = addBox(this.torso, 0.045, rand(0.3, 0.7), 0.03, crackMat, rand(-0.42, 0.42), rand(0.2, 0.95), 0.5, 0, 0, rand(-0.5, 0.5));
        crack.castShadow = false;
      }

  if (!this.input.touchActive && !document.pointerLockElement) {
    try { this.canvas.requestPointerLock?.(); } catch { /* pointer lock needs a gesture in some browsers */ }
  }
}

beginIntro(duration = 1.7) {
  this.state = 'intro';
  this.introTimer = duration;
  this.ui.introAct.textContent = `ACT ${['', 'I', 'II', 'III'][this.act]}`;
  this.ui.introName.textContent = this.boss.name;
  this.ui.introEpithet.textContent = this.boss.epithet;
  this.ui.intro.classList.add('is-active');
  this.player.state = 'idle';
  this.player.stateTime = 0;
}

endIntro() {
  this.state = 'playing';
  this.ui.intro.classList.remove('is-active');
  if (this.boss) {
    this.boss.think = 0.8;
    this.boss.cooldown = 0.9;
    this.audio.roar(this.boss.kind === 'king');
  }
}

nextBoss() {
  const idx = BOSS_ORDER.indexOf(this.bossKind);
  if (idx >= BOSS_ORDER.length - 1) {
    this.victory();
    return;
  }
  this.audio.ui();
  this.player.restoreAfterBoss();
  this.player.pos.set(0, 0.36, 8.5);
  this.player.yaw = Math.PI;
  this.player.velocity.set(0, 0, 0);
  this.player.root.visible = true;
  this.cameraYaw = Math.PI;
  this.cameraPitch = 0.14;
  this.spawnBoss(BOSS_ORDER[idx + 1]);
  this.boss.spawnAt(new THREE.Vector3(0, 0.36, -4.2));
  this.boss.think = 999;
  this.ui.bossHp.style.transform = 'scaleX(1)';
  this.ui.bossHpGhost.style.transform = 'scaleX(1)';
  this.beginIntro(1.8);
  this.setToast(`ACT ${['', 'I', 'II', 'III'][this.act]} — ${['', 'THE FIRST GATE', 'THE HOLLOW VAULT', 'THE LAST THRONE'][this.act]}`, false, 1.8);
  this.updateHUD();
  this.updateBossUI(this.boss);
}

retryBoss() {
  if (!this.boss) return;
  this.audio.init();
  this.deaths++;
  this.ui.death.classList.remove('is-active');
  this.ui.hud.classList.remove('is-hidden');
  document.body.classList.add('playing');
  this.player.reset();
  this.player.pos.set(0, 0.36, 8.5);
  this.player.yaw = Math.PI;
  this.player.root.visible = true;
  this.player.lockOn = false;
  this.cameraYaw = Math.PI;
  this.cameraPitch = 0.14;
  this.boss.spawnAt(new THREE.Vector3(0, 0.36, -4.2));
  this.boss.think = 999;
  this.beginIntro(0.75);
  this.updateHUD();
  this.updateBossUI(this.boss);
  this.input.flush();
  this.setToast('RISE AGAIN', false, 1.0);
  if (!this.input.touchActive) {
    try { this.canvas.requestPointerLock?.(); } catch { /* ignore */ }
  }
}

returnToMenu() {
  this.input.releasePointer();
  this.input.flush();
  this.ui.death.classList.remove('is-active');
  this.ui.victory.classList.remove('is-active');
  this.ui.pause.classList.remove('is-active');
  this.ui.intro.classList.remove('is-active');
  this.ui.hud.classList.add('is-hidden');
  this.ui.menu.classList.add('is-active');
  this.ui.bossPlate.classList.remove('is-active');
  document.body.classList.remove('playing');
  this.state = 'menu';
  this.spawnBoss('warden');
  this.boss.think = 999;
  this.boss.cooldown = 999;
  this.player.reset();
  this.player.pos.set(0, 0.36, 8.5);
  this.player.yaw = Math.PI;
  this.player.root.visible = true;
  this.cameraYaw = Math.PI;
  this.cameraPitch = 0.14;
  this.menuTime = 0;
  this.updateBestRun();
}

pause() {
  if (this.state !== 'playing') return;
  this.state = 'paused';
  this.ui.pause.classList.add('is-active');
  this.input.releasePointer();
  this.input.flush();
  this.audio.ui();
}

resume() {
  if (this.state !== 'paused') return;
  this.state = 'playing';
  this.ui.pause.classList.remove('is-active');
  this.input.flush();
  if (!this.input.touchActive) {
    try { this.canvas.requestPointerLock?.(); } catch { /* ignore */ }
  }
}

playerDied() {
  if (this.state === 'dead') return;
  this.state = 'dying';
  this.deathTimer = 1.35;
  this.input.releasePointer();
  this.ui.hud.classList.remove('is-hidden');
  this.audio.death();
}

showDeath() {
  this.state = 'dead';
  this.ui.deathTip.textContent = this.parryCount === 0
    ? 'The white glint is the promise. Answer it sooner.'
    : 'Patience is a weapon. Raise your guard, then strike.';
  this.ui.death.classList.add('is-active');
  document.body.classList.remove('playing');
  this.updateBestRun();
}

victory() {
  this.state = 'victory';
  this.ui.hud.classList.add('is-hidden');
  this.ui.victory.classList.add('is-active');
  document.body.classList.remove('playing');
  this.input.releasePointer();
  this.audio.victory();
  this.ui.finalTime.textContent = formatTime(this.runTime);
  this.ui.finalParries.textContent = String(this.parryCount);
  this.ui.finalDeaths.textContent = String(this.deaths);
  this.ui.finalRank.textContent = this.rank();
  this.saveBestRun();
  this.updateBestRun();
}

rank() {
  const parries = this.parryCount;
  const deaths = this.deaths;
  if (deaths === 0 && parries >= 10) return 'S';
  if (deaths <= 1 && parries >= 6) return 'A';
  if (deaths <= 3) return 'B';
  return 'C';
}

hitBoss(damage, poise, player, kind) {
  if (!this.boss || !this.boss.alive) return false;
  this.boss.takeDamage(damage, poise, player, kind);
  this.updateBossUI(this.boss);
  return true;
}

bossParried(boss, player) {
  this.parryCount++;
  this.updateParryCount();
  player.stamina = Math.min(player.maxStamina, player.stamina + 18);
  player.parryGlow = 1;
  player.invuln = Math.max(player.invuln, 0.7);
  this.parryFlashTimer = 0.18;
  this.ui.parryFlash.classList.add('hit');
  this.hitStop(0.08);
  this.slowMotion(0.3, 0.35);
  this.cameraShake(0.5);
  this.audio.parry();
  this.effects.flash(new THREE.Vector3(boss.pos.x, 2.4, boss.pos.z), { color: 0xfff0c0, size: 5.2, life: 0.55 });
  this.effects.burst(new THREE.Vector3(boss.pos.x, 2.3, boss.pos.z), { color: 0xffe1a0, count: 60, speed: 8, size: 0.13, gravity: 2, life: 1.0 });
  this.effects.ring(boss.pos, { color: 0xffe1a0, radius: 7, life: 0.8 });
  this.setToast('PARRY', false, 0.8);
  boss.stagger();
  this.updateBossUI(boss);
}

bossStaggered(boss) {
  this.ui.bossStagger.classList.add('is-on');
  this.setToast('GUARD BROKEN — STRIKE TO RIPOSTE', false, 1.7);
}

bossRecovered(boss) {
  this.ui.bossStagger.classList.remove('is-on');
}

bossPhaseTwo(boss) {
  this.ui.bossPhase.textContent = 'PHASE II';
  this.ui.bossPhase.style.color = '#ffb18a';
  this.setToast('THE CROWN REMEMBERS', true, 2.0);
  this.audio.roar(true);
}

bossDefeated(boss) {
  this.ui.bossStagger.classList.remove('is-on');
  this.state = 'vanquish';
  this.transitionTimer = 3.2;
  this.setToast('VANQUISHED', false, 2.6);
  this.saveBestRun();
  this.updateBestRun();
}

setToast(text, danger = false, duration = 1.2) {
  this.ui.toast.textContent = text;
  this.ui.toast.classList.toggle('is-danger', danger);
  this.ui.toast.classList.add('is-on');
  this.toastTimer = duration;
}

updateCombo(n) {
  this.combo = n;
  this.comboTimer = 2.4;
  this.ui.comboNum.textContent = String(n);
  this.ui.combo.classList.toggle('is-on', n >= 2);
}

updateParryCount() {
  this.ui.parryCount.textContent = String(this.parryCount);
}

updateBossUI(boss) {
  if (!boss) return;
  const ratio = boss.hpRatio;
  this.ui.bossHp.style.transform = `scaleX(${ratio})`;
  this.ui.bossHpGhost.style.transform = `scaleX(${ratio})`;
  if (boss.phase === 2) this.ui.bossPhase.textContent = 'PHASE II';
  this.ui.bossStagger.classList.toggle('is-on', boss.isStaggered);
}

updateHUD() {
  const p = this.player;
  this.ui.hpBar.style.transform = `scaleX(${p.hpRatio})`;
  this.ui.hpGhost.style.transform = `scaleX(${p.hpRatio})`;
  this.ui.hpText.textContent = String(Math.ceil(p.hp));
  this.ui.staminaBar.style.transform = `scaleX(${p.staminaRatio})`;
  this.ui.staminaBar.classList.toggle('is-low', p.staminaRatio < 0.25);
  this.ui.playerSigil.classList.toggle('low', p.hpRatio < 0.32);
  const flasks = this.ui.flasks.querySelectorAll('.flask');
  flasks.forEach((f, i) => f.classList.toggle('full', i < p.flasks));
  this.ui.timer.textContent = formatTime(this.runTime);
}

playerAttackStarted(heavy) {
  this.fovKick = heavy ? 3.4 : 1.5;
}

playerParryStarted() {
  this.fovKick = 0.8;
}

playerRiposteStarted(boss) {
  this.fovKick = 4.5;
  this.cameraShake(0.25);
}

bossTelegraph(boss, attack) {
  this.fovKick = Math.max(this.fovKick, attack.kind === 'slam' ? 2.2 : 1.1);
}

damageFlash() {
  this.hitFlashTimer = 0.22;
  this.ui.damageFlash.classList.add('hit');
  this.lastDamage = this.player.lastDamage;
}

cameraShake(amount) {
  this.shake = Math.max(this.shake, amount);
}

hitStop(seconds) {
  this.hitstopTimer = Math.max(this.hitstopTimer, seconds);
}

slowMotion(scale, seconds) {
  this.slowScale = scale;
  this.slowTimer = Math.max(this.slowTimer, seconds);
}

loadBestRun() {
  try {
    this.best = JSON.parse(localStorage.getItem('ashen-vow-best') || 'null');
  } catch { this.best = null; }
}

saveBestRun() {
  if (this.state === 'menu') return;
  if (!this.best || this.runTime < this.best.time) {
    this.best = { time: this.runTime, parries: this.parryCount, rank: this.rank() };
    try { localStorage.setItem('ashen-vow-best', JSON.stringify(this.best)); } catch { /* ignore */ }
  }
}

updateBestRun() {
  this.loadBestRun();
  this.ui.bestRun.textContent = this.best ? `BEST VOW — ${formatTime(this.best.time)} · ${this.best.rank} RANK` : 'BEST VOW — UNWRITTEN';
}

processInput(dt) {
  if (this.state === 'menu') {
    if (this.input.consume('confirm')) this.startRun();
    this.input.flush();
    return;
  }
  if (this.state === 'paused') {
    if (this.input.consume('pause') || this.input.consume('confirm')) this.resume();
    this.input.flush();
    return;
  }
  if (this.state === 'dead') {
    if (this.input.consume('confirm') || this.input.consume('flask')) this.retryBoss();
    this.input.flush();
    return;
  }
  if (this.state === 'victory') {
    if (this.input.consume('confirm')) this.startRun();
    this.input.flush();
    return;
  }
  if (this.state === 'playing') {
    if (this.input.consume('pause')) { this.pause(); return; }
    for (const action of ['attack', 'heavy', 'parry', 'dodge', 'flask', 'lock']) {
      if (this.input.consume(action)) this.player.handleAction(action, this.boss);
    }
  }
}

updateCamera(dt) {
  if (this.state === 'menu') {
    this.menuTime += dt;
    const a = 0.45 + this.menuTime * 0.055;
    const r = 15.5;
    const target = new THREE.Vector3(0, 2.2, 0);
    const desired = new THREE.Vector3(Math.cos(a) * r, 4.6 + Math.sin(this.menuTime * 0.25) * 0.3, Math.sin(a) * r);
    this.camera.position.lerp(desired, 1 - Math.exp(-dt * 1.5));
    this.camera.lookAt(target);
    this.camera.fov = damp(this.camera.fov, 54, 3, dt);
    this.camera.updateProjectionMatrix();
    return;
  }

  const inp = this.lastInput || { lookX: 0, lookY: 0 };
  if (this.state === 'playing' || this.state === 'intro') {
    this.cameraYaw += inp.lookX;
    this.cameraPitch = clamp(this.cameraPitch + inp.lookY, -0.12, 0.72);
  }
  if (this.player.lockOn && this.boss && this.boss.alive) {
    const targetYaw = Math.atan2(this.boss.pos.x - this.player.pos.x, this.boss.pos.z - this.player.pos.z);

      const targetYaw = Math.atan2(this.boss.pos.x - this.player.pos.x, this.boss.pos.z - this.player.pos.z);
      let diff = targetYaw - this.cameraYaw;
      while (diff > Math.PI) diff -= Math.PI * 2;
      while (diff < -Math.PI) diff += Math.PI * 2;
      this.cameraYaw += diff * Math.min(1, dt * 3.5);
      this.cameraPitch = damp(this.cameraPitch, 0.18, 2.5, dt);
    }

    const target = new THREE.Vector3(this.player.pos.x, this.player.pos.y + 1.36, this.player.pos.z);
    const f = new THREE.Vector3(Math.sin(this.cameraYaw), 0, Math.cos(this.cameraYaw));
    const right = new THREE.Vector3(Math.cos(this.cameraYaw), 0, -Math.sin(this.cameraYaw));
    target.addScaledVector(right, 0.48);
    const horizontal = Math.cos(this.cameraPitch) * this.cameraDistance;
    const height = 1.55 + Math.sin(this.cameraPitch) * this.cameraDistance;
    const desired = target.clone().addScaledVector(f, -horizontal);
    desired.y = this.player.pos.y + height;
    if (this.state === 'intro') {
      const introTarget = this.boss ? this.boss.pos.clone().setY(2.2) : target;
      const introPos = introTarget.clone().add(new THREE.Vector3(Math.sin(this.cameraYaw + 0.18) * 10, 5.2, Math.cos(this.cameraYaw + 0.18) * 10));
      desired.lerp(introPos, 0.55);
    }
    this.camera.position.lerp(desired, 1 - Math.exp(-dt * 9));
    const look = target.clone();
    if (this.state === 'intro' && this.boss) look.lerp(this.boss.pos.clone().setY(2.2), 0.45);
    this.camera.lookAt(look);
    this.camera.fov = damp(this.camera.fov, 58 + this.fovKick, 5, dt);
    this.camera.updateProjectionMatrix();

    if (this.shake > 0.001) {
      const s = this.shake * 0.13;
      this.camera.position.x += (Math.random() - 0.5) * s;
      this.camera.position.y += (Math.random() - 0.5) * s;
      this.camera.position.z += (Math.random() - 0.5) * s;
      this.camera.rotation.z += (Math.random() - 0.5) * s * 0.12;
    }
  }

  updateUI(dt) {
    if (this.toastTimer > 0) {
      this.toastTimer -= dt;
      if (this.toastTimer <= 0) this.ui.toast.classList.remove('is-on');
    }
    if (this.hitFlashTimer > 0) {
      this.hitFlashTimer -= dt;
      if (this.hitFlashTimer <= 0) this.ui.damageFlash.classList.remove('hit');
    }
    if (this.parryFlashTimer > 0) {
      this.parryFlashTimer -= dt;
      if (this.parryFlashTimer <= 0) this.ui.parryFlash.classList.remove('hit');
    }
    if (this.comboTimer > 0) {
      this.comboTimer -= dt;
      if (this.comboTimer <= 0) this.updateCombo(0);
    }
    if (this.state !== 'menu') {
      this.updateHUD();
      this.ui.timer.textContent = formatTime(this.runTime);
    }
    const p = this.player;
    const boss = this.boss;
    const showParry = this.state === 'playing' && boss && boss.alive && boss.parryCue && boss.state === 'windup';
    this.ui.parryPrompt.classList.toggle('is-active', showParry);
    this.ui.lockBadge.classList.toggle('is-on', p.lockOn && this.state === 'playing');
    this.ui.reticle.classList.toggle('is-target', p.lockOn || (boss && boss.alive && this.state === 'playing'));
    if (boss && boss.alive) {
      this.ui.bossStagger.classList.toggle('is-on', boss.isStaggered);
      this.ui.bossHpGhost.style.transform = `scaleX(${boss.hpRatio})`;
    }
    if (this.shake > 0.001) this.shake = Math.max(0, this.shake - dt * 3.5);
    this.fovKick = damp(this.fovKick, 0, 6, dt);
    this.ui.bossOffscreen.classList.remove('is-on');
  }

  animate() {
    requestAnimationFrame(this.animate);
    const raw = Math.min(this.clock.getDelta(), 0.05);
    this.time += raw;

    if (this.hitstopTimer > 0) {
      this.hitstopTimer -= raw;
      this.timeScale = 0.045;
    } else if (this.slowTimer > 0) {
      this.slowTimer -= raw;
      this.timeScale = this.slowScale;
    } else {
      this.timeScale = damp(this.timeScale, 1, 12, raw);
    }
    const dt = raw * this.timeScale;

    this.lastInput = this.input.update();
    this.processInput(raw);

    if (this.state === 'playing') {
      this.runTime += raw;
      this.player.update(dt, this.boss);
      if (this.boss) this.boss.update(dt, this.player);
      if (this.boss && this.boss.alive) {
        this.audio.update(raw, { active: true, intensity: 0.45 + (1 - this.boss.hpRatio) * 0.55, hp: this.player.hpRatio });
      }
    } else if (this.state === 'intro') {
      this.introTimer -= raw;
      this.player.update(dt, null);
      if (this.boss) this.boss.update(dt, this.player);
      if (this.introTimer <= 0) this.endIntro();
    } else if (this.state === 'vanquish') {
      this.transitionTimer -= raw;
      this.player.update(dt, null);
      if (this.boss) this.boss.update(dt, this.player);
      if (this.transitionTimer <= 0) this.nextBoss();
    } else if (this.state === 'dying') {
      this.deathTimer -= raw;
      this.player.update(dt, this.boss);
      if (this.boss) this.boss.update(dt, this.player);
      if (this.deathTimer <= 0) this.showDeath();
    } else if (this.state === 'paused' || this.state === 'dead' || this.state === 'victory') {
      this.player.update(dt, this.boss);
      if (this.boss && this.state !== 'paused') this.boss.update(dt, this.player);
    } else if (this.state === 'menu') {
      this.player.update(dt, null);
      if (this.boss) this.boss.update(dt, this.player);
    }

    this.effects.update(dt);
    this.arena.update(raw, this.time);
    this.updateCamera(raw);
    this.updateUI(raw);
    this.composer.render();
  }
}

window.addEventListener('DOMContentLoaded', () => {
  const game = new Game();
  window.__ASHEN_VOW__ = game;
});

startDodge() {
  if (this.stamina < 22) {
    this.game.setToast('EXHAUSTED', true, 0.5);
    this.game.audio.ui();
    return;
  }
  this.stamina -= 22;
  this.staminaDelay = 0.6;
  this.state = 'roll';
  this.stateTime = 0;
  this.attackQueued = false;
  const inp = this.game.input;
  let x = inp.moveX;
  let z = inp.moveZ;
  if (Math.hypot(x, z) < 0.1) { x = 0; z = -1; }
  const cam = this.game.cameraYaw;
  const f = new THREE.Vector3(Math.sin(cam), 0, Math.cos(cam));
  const r = new THREE.Vector3(Math.cos(cam), 0, -Math.sin(cam));
  this.rollDir.copy(f).multiplyScalar(z).addScaledVector(r, x).normalize();
  this.yaw = Math.atan2(this.rollDir.x, this.rollDir.z);
  this.audio.dodge();
  this.effects.dust(this.pos, { count: 12, radius: 0.8 });
}

startParry() {
  if (this.stamina < 16) {
    this.game.setToast('EXHAUSTED', true, 0.5);
    this.game.audio.ui();
    return;
  }
  this.stamina -= 16;
  this.staminaDelay = 0.6;
  this.state = 'parry';
  this.stateTime = 0;
  this.attackQueued = false;
  this.parryGlow = 1;
  this.audio.whoosh();
  this.game.playerParryStarted();
}

startHeal() {
  if (this.flasks <= 0) {
    this.game.setToast('NO EMBERS LEFT', true, 0.8);
    this.game.audio.ui();
    return;
  }
  if (this.state === 'attack' || this.state === 'heavy') return;
  this.state = 'heal';
  this.stateTime = 0;
  this.healed = false;
  this.velocity.multiplyScalar(0.1);
  this.game.audio.cast();
}

startRiposte(boss) {
  this.state = 'riposte';
  this.stateTime = 0;
  this.riposteHit = false;
  this.riposteTarget = boss;
  this.yaw = Math.atan2(boss.pos.x - this.pos.x, boss.pos.z - this.pos.z);
  this.velocity.set(0, 0, 0);
  this.game.setToast('RIPOSTE', false, 1.0);
  this.game.playerRiposteStarted(boss);
}

update(dt, boss) {
  this.time += dt;
  if (this.state === 'dead') {
    this.deadTime += dt;
    this.animate(dt, 0);
    return;
  }
  this.stateTime += dt;
  this.invuln = Math.max(0, this.invuln - dt);
  this.comboTimer = Math.max(0, this.comboTimer - dt);
  if (this.comboTimer <= 0) this.combo = 0;
  this.staminaDelay = Math.max(0, this.staminaDelay - dt);
  if (this.staminaDelay <= 0 && this.state !== 'roll' && this.state !== 'attack' && this.state !== 'heavy') {
    this.stamina = Math.min(this.maxStamina, this.stamina + 31 * dt);
  }
  if (this.parryGlow > 0) this.parryGlow = Math.max(0, this.parryGlow - dt * 2.8);
  this.hitFlash = Math.max(0, this.hitFlash - dt * 3.5);

  if (boss && boss.alive && this.lockOn) {
    const targetYaw = Math.atan2(boss.pos.x - this.pos.x, boss.pos.z - this.pos.z);
    let diff = targetYaw - this.yaw;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    this.yaw += diff * Math.min(1, dt * 8);
  }

  switch (this.state) {
    case 'idle':
    case 'run':
      this.updateMovement(dt, boss);
      break;
    case 'attack':
    case 'heavy':
      this.updateAttack(dt, boss);
      break;
    case 'roll':
      this.updateRoll(dt);
      break;
    case 'parry':
      this.updateParry(dt);
      break;
    case 'heal':
      this.updateHeal(dt);
      break;
    case 'riposte':
      this.updateRiposte(dt);
      break;
    case 'hurt':
      this.updateHurt(dt);
      break;
  }

  this.pos.x = clamp(this.pos.x, -20.6, 20.6);
  this.pos.z = clamp(this.pos.z, -20.6, 20.6);
  const dist = Math.hypot(this.pos.x, this.pos.z);
  if (dist > 20.6) {
    this.pos.x *= 20.6 / dist;
    this.pos.z *= 20.6 / dist;
  }

  this.root.rotation.y = this.yaw;
  this.root.position.y = 0.36;
  this.animate(dt, this.velocity.length());
}

updateMovement(dt, boss) {
  const inp = this.game.input;
  const x = inp.moveX;
  const z = inp.moveZ;
  const cam = this.game.cameraYaw;
  const f = new THREE.Vector3(Math.sin(cam), 0, Math.cos(cam));
  const r = new THREE.Vector3(Math.cos(cam), 0, -Math.sin(cam));
  const desired = f.multiplyScalar(z).addScaledVector(r, x);
  const len = desired.length();
  const moving = len > 0.08;
  if (moving) desired.normalize().multiplyScalar(5.25);
  const accel = moving ? 15 : 20;
  this.velocity.x = damp(this.velocity.x, desired.x, accel, dt);
  this.velocity.z = damp(this.velocity.z, desired.z, accel, dt);
  if (this.velocity.lengthSq() > 0.04) {
    this.pos.x += this.velocity.x * dt;
    this.pos.z += this.velocity.z * dt;
  }
  if (!this.lockOn && moving) {
    const target = Math.atan2(this.velocity.x, this.velocity.z);
    let diff = target - this.yaw;
    while (diff > Math.PI) diff -= Math.PI * 2;
    while (diff < -Math.PI) diff += Math.PI * 2;
    this.yaw += diff * Math.min(1, dt * 12);
  }
  const newState = moving ? 'run' : 'idle';
  if (newState !== this.state) {
    this.state = newState;
    this.stateTime = 0;
  }
  if (moving) {
    this.footClock -= dt;
    if (this.footClock <= 0) {
      this.footClock = 0.34;
      this.audio.step();
    }
  }
  if (boss && boss.alive) {
    const dx = this.pos.x - boss.pos.x;
    const dz = this.pos.z - boss.pos.z;
    const d = Math.hypot(dx, dz);
    const min = 1.15 + this.radius;
    if (d < min && d > 0.001) {
      this.pos.x = boss.pos.x + (dx / d) * min;
      this.pos.z = boss.pos.z + (dz / d) * min;
    }
  }
}

updateAttack(dt, boss) {
  const def = this.attackDef;
  const t = this.stateTime;
  const forward = this.forward();
  if (!this.attackHit && t >= def.active) {
    this.attackHit = true;
    const dist = this.distanceToBoss(boss);
    const dot = forward.dot(new THREE.Vector3(boss.pos.x - this.pos.x, 0, boss.pos.z - this.pos.z).normalize());
    if (dist <= def.range + (boss.radius || 0) && dot > Math.cos(def.arc / 2)) {
      this.game.hitBoss(def.damage, def.poise, this, this.heavyAttack ? 'heavy' : 'light');
      this.audio.hit(this.heavyAttack);
      this.effects.burst(new THREE.Vector3(boss.pos.x, 1.5, boss.pos.z), { color: 0xffd28a, count: this.heavyAttack ? 32 : 18, speed: this.heavyAttack ? 7 : 5, size: 0.1, gravity: 6 });
      this.effects.slash(this.pos, this.yaw, { radius: def.range + 0.5, arc: def.arc, color: this.heavyAttack ? 0xffc46b : 0xc7d8df, life: 0.18, y: this.heavyAttack ? 1.3 : 1.15, tilt: 0.12 });
      this.game.cameraShake(this.heavyAttack ? 0.34 : 0.18);
      this.game.hitStop(this.heavyAttack ? 0.075 : 0.045);
      this.combo++;
      this.comboTimer = 2.4;
      this.game.updateCombo(this.combo);
    } else if (dist < 5) {
      this.effects.slash(this.pos, this.yaw, { radius: def.range, arc: def.arc, color: 0x9daeb8, life: 0.14, y: 1.1 });
    }
  }
  if (t > def.active - 0.04 && t < def.end) {
    this.pos.x += forward.x * def.lunge * dt;
    this.pos.z += forward.z * def.lunge * dt;
  }
  if (t >= def.duration) {
    if (this.attackQueued && !this.heavyAttack) {
      this.attackQueued = false;
      this.state = 'idle';
      this.stateTime = 0;
      this.startAttack(false, boss);
    } else {
      this.state = 'idle';
      this.stateTime = 0;
      this.attackQueued = false;
    }
  }
}

updateRoll(dt) {
  const t = this.stateTime / 0.52;
  const speed = 11.5 * (1 - Math.pow(t, 1.6)) + 1.5;
  this.pos.x += this.rollDir.x * speed * dt;
  this.pos.z += this.rollDir.z * speed * dt;
  this.invuln = Math.max(this.invuln, t > 0.06 && t < 0.62 ? 0.08 : 0);
  if (t > 0.25 && t < 0.7 && Math.random() < dt * 35) {
    this.effects.burst(new THREE.Vector3(this.pos.x, 0.5, this.pos.z), { color: 0x8b8172, count: 4, speed: 1.2, size: 0.12, gravity: -0.2, life: 0.5 });
  }
  if (this.stateTime >= 0.52) {
    this.state = 'idle';
    this.stateTime = 0;
  }
}

updateParry(dt) {
  if (this.stateTime > 0.3 && this.parryGlow > 0) this.parryGlow = Math.max(0, this.parryGlow - dt * 2);
  if (this.stateTime >= 0.58) {
    this.state = 'idle';
    this.stateTime = 0;
  }
}

updateHeal(dt) {
  if (!this.healed && this.stateTime >= 0.55) {
    this.healed = true;
    this.flasks--;
    this.hp = Math.min(this.maxHp, this.hp + 38);
    this.effects.flash(new THREE.Vector3(this.pos.x, 1.2, this.pos.z), { color: 0xffc46b, size: 2.2, life: 0.5 });
    this.effects.burst(new THREE.Vector3(this.pos.x, 1.1, this.pos.z), { color: 0xffb45e, count: 30, speed: 3, size: 0.12, gravity: -1, life: 1.1, upward: 1.2 });
    this.audio.heal();
    this.game.setToast('EMBER RESTORED', false, 1.0);
  }
  if (this.stateTime >= 1.15) {
    this.state = 'idle';
    this.stateTime = 0;
  }
}

updateRiposte(dt) {
  const t = this.stateTime;
  const boss = this.riposteTarget;
  if (boss) this.yaw = Math.atan2(boss.pos.x - this.pos.x, boss.pos.z - this.pos.z);
  if (!this.riposteHit && t >= 0.58) {
    this.riposteHit = true;
    if (boss && boss.alive) {
      this.game.hitBoss(260, 120, this, 'riposte');
      this.audio.hit(true);
      this.audio.parry();
      this.effects.flash(new THREE.Vector3(boss.pos.x, 2.2, boss.pos.z), { color: 0xffe6a8, size: 4.5, life: 0.55 });
      this.effects.burst(new THREE.Vector3(boss.pos.x, 2.0, boss.pos.z), { color: 0xffd27a, count: 70, speed: 10, size: 0.16, gravity: 4, life: 1.1 });
      this.effects.slash(this.pos, this.yaw, { radius: 4, arc: 1.5, color: 0xffe1a1, life: 0.32, y: 1.4, scale: 1.3 });
      this.game.cameraShake(0.7);
      this.game.hitStop(0.14);
      this.game.slowMotion(0.25, 0.5);
    }
  }
  if (t >= 1.28) {
    this.state = 'idle';
    this.stateTime = 0;
  }
}

updateHurt(dt) {
  this.pos.x += this.velocity.x * dt;
  this.pos.z += this.velocity.z * dt;
  this.velocity.multiplyScalar(Math.pow(0.03, dt));
  if (this.stateTime >= 0.34) {
    this.state = 'idle';
    this.stateTime = 0;
  }
}

takeDamage(amount, source, { unblockable = false } = {}) {
  if (!this.alive || this.invuln > 0 || this.state === 'riposte') return false;
  const dx = this.pos.x - source.x;
  const dz = this.pos.z - source.z;
  const len = Math.hypot(dx, dz) || 1;
  this.hp = Math.max(0, this.hp - amount);
  this.lastDamage = amount;
  this.hitFlash = 1;
  this.invuln = 0.72;
  this.combo = 0;
  this.comboTimer = 0;
  this.game.updateCombo(0);
  this.game.cameraShake(0.55);
  this.game.damageFlash();
  this.game.hitStop(0.06);
  this.effects.burst(new THREE.Vector3(this.pos.x, 1.1, this.pos.z), { color: 0x9d2329, count: 26, speed: 4.5, size: 0.11, gravity: 9, life: 0.7 });
  this.audio.damage();
  this.velocity.set((dx / len) * 5.5, 0, (dz / len) * 5.5);
  if (this.hp <= 0) {
    this.die();
  } else {
    this.state = 'hurt';
    this.stateTime = 0;
    this.game.setToast(unblockable ? 'UNBLOCKABLE' : 'WOUNDED', true, 0.6);
  }
  return true;
}

die() {
  this.state = 'dead';
  this.stateTime = 0;
  this.deadTime = 0;
  this.velocity.set(0, 0, 0);
  this.audio.death();
  this.game.playerDied();
}

animate(dt, speed) {
  const t = this.time;
  const running = this.state === 'run';
  this.walkPhase += dt * (running ? 10.2 : 2.0);
  const ph = this.walkPhase;
  const breath = Math.sin(t * 2.1) * 0.008;

  this.body.position.set(0, 0, 0);
  this.body.rotation.set(0, 0, 0);
  this.torso.position.y = 1.18 + breath;
  this.torso.rotation.set(0, 0, 0);
  this.head.rotation.set(0, 0, 0);
  this.armR.rotation.set(-0.16, 0, 0.12);
  this.armL.rotation.set(-0.12, 0, -0.15);
  this.elbowR.rotation.set(0.08, 0, 0);
  this.elbowL.rotation.set(0.12, 0, 0);
  this.legR.rotation.set(0, 0, 0);
  this.legL.rotation.set(0, 0, 0);
  this.cape.rotation.set(0.12, 0, 0);
  this.shield.rotation.set(0, 0, 0.08);
  this.weapon.rotation.set(0, 0, 0);

  if (running) {
    const amp = clamp(speed / 5.25, 0, 1);
    this.legR.rotation.x = Math.sin(ph) * 0.68 * amp;
    this.legL.rotation.x = -Math.sin(ph) * 0.68 * amp;
    this.armR.rotation.x = -0.1 - Math.sin(ph) * 0.3 * amp;
    this.armL.rotation.x = -0.1 + Math.sin(ph) * 0.3 * amp;
    this.torso.rotation.z = Math.sin(ph * 2) * 0.035 * amp;
    this.body.position.y = Math.abs(Math.sin(ph)) * 0.045 * amp;
    this.cape.rotation.x = 0.3 + Math.sin(ph * 2) * 0.08;
    this.capePivot.rotation.x = -0.08 * amp;
  } else {
    this.armR.rotation.x += Math.sin(t * 2.1) * 0.015;
    this.armL.rotation.x += Math.sin(t * 2.1 + 1) * 0.015;
    this.cape.rotation.x = 0.12 + Math.sin(t * 1.3) * 0.025;
    this.capePivot.rotation.x = 0;
  }

  if (this.state === 'attack' || this.state === 'heavy') {
    const def = this.attackDef;
    const raw = clamp(this.stateTime / def.duration, 0, 1);
    const t1 = clamp(raw / 0.38, 0, 1);
    const t2 = clamp((raw - 0.38) / 0.3, 0, 1);
    const wind = 1 - Math.pow(1 - t1, 3);
    const swing = t2 * t2 * (3 - 2 * t2);
    const heavy = this.heavyAttack;
    this.armR.rotation.x = heavy ? lerp(-0.2, -2.75, wind) - swing * 3.3 : lerp(-0.2, -2.35, wind) - swing * 2.9;
    this.armR.rotation.z = heavy ? lerp(0.15, 0.45, wind) - swing * 0.35 : lerp(0.15, 0.5, wind) - swing * 0.8;
    this.elbowR.rotation.x = lerp(0.1, 0.55, wind) - swing * 0.2;
    this.torso.rotation.y = lerp(0, heavy ? -0.65 : -0.55, wind) + swing * (heavy ? 1.1 : 0.95);
    this.torso.rotation.x = swing * (heavy ? 0.35 : 0.2);
    this.armL.rotation.x = lerp(-0.2, -0.7, wind) + swing * 0.5;
    this.armL.rotation.z = -0.3;
    this.legR.rotation.x = lerp(0, -0.25, swing);
    this.legL.rotation.x = lerp(0, 0.3, swing);
    this.cape.rotation.x = 0.25 + swing * 0.45;
    this.capePivot.rotation.x = -0.1 - swing * 0.2;
  } else if (this.state === 'roll') {
    const p = clamp(this.stateTime / 0.52, 0, 1);
    this.body.rotation.x = -p * Math.PI * 2;
    this.body.position.y = Math.sin(p * Math.PI) * 0.35;
    this.armR.rotation.x = -1.1;
    this.armL.rotation.x = -1.1;
    this.elbowR.rotation.x = 1.2;
    this.elbowL.rotation.x = 1.2;
    this.legR.rotation.x = -1.0;
    this.legL.rotation.x = -0.8;
    this.cape.rotation.x = 0.6;
  } else if (this.state === 'parry') {
    const p = clamp(this.stateTime / 0.2, 0, 1);
    this.armL.rotation.x = lerp(-0.12, -1.35, Math.min(1, p * 2.2));
    this.armL.rotation.z = lerp(-0.15, 0.55, Math.min(1, p * 2.2));
    this.elbowL.rotation.x = lerp(0.12, 0.9, Math.min(1, p * 2.2));
    this.armR.rotation.x = -0.55;
    this.armR.rotation.z = -0.2;
    this.torso.rotation.y = -0.25;
    this.torso.rotation.x = -0.05;
    this.shield.rotation.z = 0.6;
  } else if (this.state === 'heal') {
    const p = Math.sin(clamp(this.stateTime / 1.15, 0, 1) * Math.PI);
    this.armL.rotation.x = lerp(-0.12, -1.45, p);
    this.armL.rotation.z = lerp(-0.15, 0.65, p);
    this.elbowL.rotation.x = 1.1 * p;
    this.armR.rotation.x = -0.5;
    this.torso.rotation.x = -0.12 * p;
    this.head.rotation.x = 0.15 * p;
  } else if (this.state === 'riposte') {
    const t0 = clamp((this.stateTime - 0.28) / 0.32, 0, 1);
    const thrust = t0 * t0 * (3 - 2 * t0);
    this.armR.rotation.x = lerp(-2.3, 0.55, thrust);
    this.armR.rotation.z = lerp(0.5, 0.05, thrust);
    this.elbowR.rotation.x = lerp(0.9, 0.0, thrust);
    this.torso.rotation.y = lerp(-0.6, 0.35, thrust);
    this.torso.rotation.x = 0.18 * thrust;
    this.armL.rotation.x = -0.9;
    this.legR.rotation.x = -0.3;
    this.legL.rotation.x = 0.2;
    this.cape.rotation.x = 0.45;
  } else if (this.state === 'hurt') {
    const p = clamp(this.stateTime / 0.34, 0, 1);
    this.body.rotation.x = -0.18 * Math.sin(p * Math.PI);
    this.torso.rotation.x = 0.25 * Math.sin(p * Math.PI);
    this.armR.rotation.x = -0.8;
    this.armL.rotation.x = -0.9;
    this.head.rotation.x = -0.2;
  } else if (this.state === 'dead') {
    const p = clamp(this.deadTime / 1.3, 0, 1);
    const ease = p * p * (3 - 2 * p);
    this.body.rotation.z = ease * 1.45;
    this.body.position.y = -ease * 0.15;

    }
  }

  this.aura = new THREE.Sprite(new THREE.SpriteMaterial({ map: makeGlowTexture(256, 'rgba(255,255,255,0.75)', 'rgba(0,0,0,0)'), color: c.color, transparent: true, opacity: 0.16, depthWrite: false, blending: THREE.AdditiveBlending }));
  this.aura.position.set(0, 2.2, -0.3);
  this.aura.scale.set(5, 7, 1);
  this.model.add(this.aura);

  this.light = new THREE.PointLight(c.color, 13, 12, 2);
  this.light.position.set(0, 2.5, 0.7);
  this.model.add(this.light);

  this.weaponTipGlow = new THREE.Sprite(new THREE.SpriteMaterial({ map: makeGlowTexture(128, 'rgba(255,255,255,1)', 'rgba(255,200,100,0)'), color: 0xffe5b0, transparent: true, opacity: 0, depthWrite: false, blending: THREE.AdditiveBlending }));
  this.weaponTipGlow.position.set(0, this.kind === 'king' ? 2.55 : 3.15, 0);
  this.weapon.add(this.weaponTipGlow);

  this.root.traverse((o) => {
    if (o.isMesh) { o.castShadow = true; o.receiveShadow = true; }
  });
}

buildKnightHead(armor, armorDark, trim, eyeMat) {
  const helm = new THREE.Mesh(new THREE.CapsuleGeometry(0.32, 0.26, 4, 12), armor);
  helm.position.y = 0.22;
  helm.castShadow = true;
  this.head.add(helm);
  addBox(this.head, 0.58, 0.16, 0.12, armorDark, 0, 0.25, 0.27);
  addBox(this.head, 0.42, 0.035, 0.02, eyeMat, 0, 0.26, 0.34);
  addCone(this.head, 0.1, 0.7, trim, -0.4, 0.55, 0, 0, 0, -0.55);
  addCone(this.head, 0.1, 0.7, trim, 0.4, 0.55, 0, 0, 0, 0.55);
  addCone(this.head, 0.08, 0.42, armorDark, 0, 0.55, -0.18, -0.2, 0, 0);
  addBox(this.head, 0.18, 0.22, 0.4, armorDark, 0, 0.06, -0.06);
}

buildChoristerHead(armor, armorDark, trim, eyeMat, cloth) {
  const hood = new THREE.Mesh(new THREE.ConeGeometry(0.42, 0.95, 8), cloth);
  hood.position.y = 0.32;
  hood.rotation.x = 0.06;
  hood.castShadow = true;
  this.head.add(hood);
  const mask = new THREE.Mesh(new THREE.CircleGeometry(0.23, 16), standard(0xd8d3c4, { roughness: 0.5, metalness: 0.1 }));
  mask.position.set(0, 0.2, 0.31);
  this.head.add(mask);
  for (const side of [-1, 1]) {
    const eye = addBox(this.head, 0.07, 0.025, 0.02, eyeMat, side * 0.09, 0.25, 0.335);
    eye.rotation.z = side * 0.2;
  }
  addBox(this.head, 0.1, 0.28, 0.05, trim, 0, 0.08, 0.32);
}

buildWeapon(steel, trim, armorDark) {
  const kind = this.kind;
  if (kind === 'king') {
    const handle = new THREE.Mesh(new THREE.CylinderGeometry(0.055, 0.065, 2.2, 8), standard(0x241711, { roughness: 0.9 }));
    handle.position.y = 0.45;
    this.weapon.add(handle);
    addBox(this.weapon, 0.75, 0.14, 0.22, trim, 0, 1.55, 0);
    const blade = addBox(this.weapon, 0.85, 1.55, 0.1, steel, 0.12, 2.28, 0, 0, 0, -0.12);
    blade.castShadow = true;
    addBox(this.weapon, 0.26, 1.1, 0.08, armorDark, -0.34, 2.28, 0, 0, 0, 0.25);
    addCone(this.weapon, 0.24, 0.6, steel, 0.54, 2.98, 0, 0, 0, -0.3);
    this.blade = blade;
    this.bladeLen = 3.1;
  } else {
    const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.055, 0.55, 8), standard(0x241711, { roughness: 0.9 }));
    grip.position.y = 0.1;
    this.weapon.add(grip);
    addBox(this.weapon, 0.75, 0.1, 0.16, trim, 0, 0.36, 0);
    addSphere(this.weapon, 0.09, trim, 0, -0.2, 0);
    const blade = addBox(this.weapon, 0.2, 2.65, 0.07, steel, 0, 1.7, 0);
    blade.castShadow = true;
    addCone(this.weapon, 0.1, 0.48, steel, 0, 3.15, 0);
    addBox(this.weapon, 0.035, 2.1, 0.075, new THREE.MeshBasicMaterial({ color: this.config.eye }), 0, 1.7, 0.005);
    this.blade = blade;
    this.bladeLen = 3.3;
  }
}

buildTwinBlade(group, steel, trim) {
  const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.04, 0.45, 8), standard(0x241711, { roughness: 0.9 }));
  group.add(grip);
  addBox(group, 0.44, 0.07, 0.1, trim, 0, 0.24, 0);
  const blade = addBox(group, 0.1, 1.8, 0.04, steel, 0, 1.16, 0, 0, 0, 0.04);
  blade.castShadow = true;
  addCone(group, 0.05, 0.34, steel, 0.04, 2.16, 0, 0, 0, 0.04);
  addBox(group, 0.02, 1.4, 0.045, new THREE.MeshBasicMaterial({ color: this.config.eye }), 0.015, 1.15, 0.005);
}

clearHazards() {
  for (const p of this.projectiles) {
    this.scene.remove(p.mesh);
    p.mesh.geometry.dispose();
    p.mesh.material.dispose();
  }
  this.projectiles.length = 0;
  for (const h of this.hazards) {
    if (h.mesh) { this.scene.remove(h.mesh); h.mesh.geometry.dispose(); h.mesh.material.dispose(); }
    if (h.ring) { this.scene.remove(h.ring); h.ring.geometry.dispose(); h.ring.material.dispose(); }
  }
  this.hazards.length = 0;
}

spawnAt(pos) {
  this.clearHazards();
  this.pos.copy(pos);
  this.root.position.copy(pos);
  this.root.position.y = 0.36;
  this.state = 'idle';
  this.stateTime = 0;
  this.cooldown = 1.4;
  this.hp = this.maxHp;
  this.staggerMeter = 0;
  this.phase = 1;
  this.phaseTransition = false;
  this.defeated = false;
  this.attack = null;
  this.staggerTimer = 0;
  this.blink = 0;
  this.windupSound = false;
  this.blinked = false;
  this.model.visible = true;
  this.model.position.y = 0;
  this.root.rotation.set(0, 0, 0);
}

chooseAttack(player) {
  const dist = this.distanceTo(player.pos);
  const pool = this.config.attacks.filter((a) => dist >= a.min && dist <= a.max && (!a.phase2 || this.phase === 2));
  if (!pool.length) return null;
  const total = pool.reduce((s, a) => s + (a.weight || 1), 0);
  let r = Math.random() * total;
  for (const a of pool) {
    r -= (a.weight || 1);
    if (r <= 0) return a;
  }
  return pick(pool);
}

beginAttack(attack) {
  this.attack = attack;
  this.state = 'windup';
  this.stateTime = 0;
  this.attackTime = 0;
  this.hitIndex = 0;
  this.attackHit = false;
  this.parryCue = false;
  this.weaponGlow = 0;
  this.windupSound = false;
  this.blinked = false;
  this.game.bossTelegraph(this, attack);
  this.audio.whoosh();
}

update(dt, player) {
  this.stateTime += dt;
  this.attackTime += dt;
  this.hitFlash = Math.max(0, this.hitFlash - dt * 4);
  this.weaponGlow = Math.max(0, this.weaponGlow - dt * 3.2);
  this.tipFlash = Math.max(0, this.tipFlash - dt * 5);
  this.updateProjectiles(dt, player);
  this.updateHazards(dt, player);
  this.hover = this.config.hover ? this.config.hover + Math.sin(this.game.time * 1.8 + 2) * 0.09 : 0;

  if (this.state === 'dead') {
    this.deadTime += dt;
    this.animate(dt, player);
    this.updateGlow(dt);
    return;
  }

  if (this.hp <= this.maxHp * 0.5 && this.phase === 1 && this.kind === 'king') {
    this.enterPhaseTwo();
  }

  this.cooldown = Math.max(0, this.cooldown - dt);
  const dist = this.distanceTo(player.pos);
  this.parryCue = false;

  switch (this.state) {
    case 'idle': {
      this.face(player, dt, 3.2);
      this.think -= dt;
      if (this.think <= 0 && this.cooldown <= 0) {
        const attack = this.chooseAttack(player);
        if (attack) this.beginAttack(attack);
        else if (dist > 6) {
          this.state = 'approach';
          this.stateTime = 0;
          this.think = rand(0.6, 1.4);
        } else {
          this.think = rand(0.25, 0.6);
        }
      }
      break;
    }
    case 'approach': {
      this.face(player, dt, 5);
      const forward = this.forward();
      const step = this.speed * dt;
      if (dist > 4.8) {
        this.pos.x += forward.x * step;
        this.pos.z += forward.z * step;
      }
      this.walkPhase += dt * 7;
      if (this.stateTime > 1.6 || dist < 4.9) {
        this.state = 'idle';
        this.stateTime = 0;
        this.think = rand(0.05, 0.3);
      }
      break;
    }
    case 'windup': {
      const a = this.attack;
      this.face(player, dt, 1.6);
      const p = clamp(this.stateTime / a.windup, 0, 1);
      this.weaponGlow = p > 0.5 ? (p - 0.5) * 2 : 0;
      if (a.parryable && p > 0.56) this.parryCue = true;
      if (a.kind === 'blink' && p > 0.38 && !this.blinked) {
        this.blinked = true;
        this.blink = 1;
        this.teleportBehind(player);
        this.effects.flash(new THREE.Vector3(this.pos.x, 1.6, this.pos.z), { color: 0xbdeeff, size: 4, life: 0.4 });
      }
      if (p > 0.7 && !this.windupSound) {
        this.windupSound = true;
        this.audio.whoosh();
        this.tipFlash = 1;
      }
      if (this.stateTime >= a.windup) {
        this.state = 'active';
        this.stateTime = 0;
        this.windupSound = false;
        this.blinked = false;
        this.doImpact(player);
      }
      break;
    }
    case 'active': {
      const a = this.attack;
      if (a.kind === 'charge') {
        const forward = this.forward();
        this.pos.x += forward.x * 14 * dt;
        this.pos.z += forward.z * 14 * dt;
        if (!this.attackHit) this.strikePlayer(player, a);
      }
      if (a.kind === 'lunge') {
        const forward = this.forward();
        this.pos.x += forward.x * 8 * dt;
        this.pos.z += forward.z * 8 * dt;
      }
      if (a.kind === 'flurry') {
        for (let i = this.hitIndex; i < a.hits.length; i++) {
          if (this.state !== 'active') break;
          if (this.stateTime >= a.hits[i]) {
            this.hitIndex = i + 1;
            this.strikePlayer(player, a, 0.05);
          }
        }
      }
      if (this.stateTime >= a.active) {
        this.state = 'recovery';
        this.stateTime = 0;
      }
      break;
    }
    case 'recovery': {
      this.face(player, dt, 1.2);
      if (this.stateTime >= this.attack.recovery) {
        this.state = 'idle';
        this.stateTime = 0;
        this.cooldown = this.attack.cooldown * (this.phase === 2 ? 0.65 : 1);
        this.think = rand(0.15, 0.55);
        this.attack = null;
        this.windupSound = false;
      }
      break;
    }
    case 'stagger': {
      this.staggerTimer -= dt;
      if (this.staggerTimer <= 0) {
        this.state = 'idle';
        this.stateTime = 0;
        this.cooldown = 0.4;
        this.staggerMeter = 0;
        this.game.bossRecovered(this);
      }
      break;
    }
    case 'phase': {
      if (this.stateTime > 2.1) {
        this.state = 'idle';
        this.stateTime = 0;
        this.cooldown = 0.6;
        this.think = 0.2;
      }
      break;
    }
  }

  if (this.state !== 'dead') {
    this.pos.x = clamp(this.pos.x, -21, 21);
    this.pos.z = clamp(this.pos.z, -21, 21);
    const centerDist = Math.hypot(this.pos.x, this.pos.z);
    if (centerDist > 21) {
      this.pos.x *= 21 / centerDist;
      this.pos.z *= 21 / centerDist;
    }
    this.root.position.set(this.pos.x, 0.36 + this.hover, this.pos.z);
    this.root.rotation.y = this.yaw;
    this.animate(dt, player);
    this.updateGlow(dt);
  }
}

updateGlow(dt) {
  const p = this.state === 'windup' ? clamp(this.stateTime / this.attack.windup, 0, 1) : 0;
  const active = this.state === 'active' ? 1 : 0;
  const glow = Math.max(this.weaponGlow * 2.5, this.tipFlash * 2.5, active * 0.6);
  if (this.weaponMat) this.weaponMat.emissiveIntensity = 0.3 + glow * 5.5;
  if (this.weaponMat) this.weaponMat.emissive.setHex(glow > 1.4 ? 0xfff0c0 : this.config.eye);
  if (this.weaponTipGlow) {
    this.weaponTipGlow.material.opacity = clamp(this.weaponGlow * 1.5 + this.tipFlash, 0, 1);
    this.weaponTipGlow.scale.setScalar(0.7 + this.tipFlash * 1.4);
  }
  if (this.eyeMat) this.eyeMat.color.setHex(this.hitFlash > 0.2 ? 0xffffff : this.config.eye);
  if (this.aura) {
    this.aura.material.opacity = 0.11 + Math.sin(this.game.time * 2.2) * 0.025 + (this.phase === 2 ? 0.1 : 0) + this.weaponGlow * 0.12;
  }
  if (this.light) this.light.intensity = 16 + Math.sin(this.game.time * 3) * 3 + this.weaponGlow * 30 + (this.phase === 2 ? 18 : 0);
  if (this.chestGlow) this.chestGlow.scale.setScalar(1 + this.weaponGlow * 0.7 + Math.sin(this.game.time * 2.8) * 0.08);
  if (this.halo) {
    this.halo.rotation.z += dt * 0.4;
    this.halo.material.opacity = 0.45 + Math.sin(this.game.time * 2) * 0.15;
  }
}

face(player, dt, speed) {
  const target = Math.atan2(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
  let diff = target - this.yaw;
  while (diff > Math.PI) diff -= Math.PI * 2;
  while (diff < -Math.PI) diff += Math.PI * 2;
  this.yaw += diff * Math.min(1, dt * speed);
}

distanceTo(pos) {
  return Math.hypot(pos.x - this.pos.x, pos.z - this.pos.z);
}

doImpact(player) {
  const a = this.attack;
  if (!a) return;
  this.tipFlash = 1;
  this.effects.flash(new THREE.Vector3(this.pos.x, 2.2, this.pos.z), { color: this.config.color, size: 2.4, life: 0.25 });
  if (a.kind === 'slam') {
    this.effects.ring(this.pos, { color: this.config.color, radius: a.aoe, life: 0.65, width: 0.2 });
    this.effects.burst(new THREE.Vector3(this.pos.x, 0.7, this.pos.z), { color: this.config.color, count: 36, speed: 7, size: 0.13, gravity: 4 });
    this.spawnShockwave(this.pos.clone(), a.aoe, 24, this.config.color);
  } else if (a.kind === 'sweep' || a.kind === 'twin' || a.kind === 'blink' || a.kind === 'lunge' || a.kind === 'flurry') {
    this.effects.slash(new THREE.Vector3(this.pos.x, this.pos.y || 0.36, this.pos.z), this.yaw, { radius: a.range || 4, arc: a.arc || 2.4, color: this.config.color, life: 0.2, y: 1.5, scale: 1.2 });
  } else if (a.kind === 'fan') {
    this.castFan(player);
  } else if (a.kind === 'eruption') {
    this.castEruption(player);
  }
  if (['sweep', 'twin', 'blink', 'lunge'].includes(a.kind)) {
    this.strikePlayer(player, a, 0);
  }
}

strikePlayer(player, a, grace = 0) {
  const dist = this.distanceTo(player.pos);
  const toPlayer = new THREE.Vector3(player.pos.x - this.pos.x, 0, player.pos.z - this.pos.z).normalize();
  const dot = this.forward().dot(toPlayer);
  const hitRange = a.aoe || (a.kind === 'charge' ? 2.8 : a.kind === 'lunge' ? 3.4 : (a.range || 5));
  const inRange = dist <= hitRange + player.radius;
  const inArc = a.aoe || !a.arc || dot > Math.cos(a.arc / 2);
  if (!inRange || !inArc) return;
  if (player.isParryActive && a.parryable) {
    this.game.bossParried(this, player);
    return;
  }
  if (player.state === 'roll' && player.invuln > 0) return;
  this.hitPlayer(player, a);
}

hitPlayer(player, a) {
  if (this.attackHit && this.attack && this.attack.kind !== 'flurry') return;
  if (this.attack && this.attack.kind !== 'flurry') this.attackHit = true;
  player.takeDamage(a.damage, this.pos, { unblockable: !a.parryable });
}

castFan(player) {
  const count = 5;
  const base = Math.atan2(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
  for (let i = 0; i < count; i++) {
    const spread = (i - (count - 1) / 2) * 0.18;
    this.spawnProjectile(base + spread);
  }
  this.audio.cast();
  this.effects.flash(new THREE.Vector3(this.pos.x, 2.4, this.pos.z), { color: 0xa9eaff, size: 3.4, life: 0.45 });
}

spawnProjectile(angle) {
  const geo = new THREE.SphereGeometry(0.18, 8, 6);
  const mat = new THREE.MeshBasicMaterial({ color: 0xbcefff });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(this.pos.x, 2.2, this.pos.z);
  const glow = new THREE.Sprite(new THREE.SpriteMaterial({ map: makeGlowTexture(128, 'rgba(190,240,255,0.9)', 'rgba(80,160,255,0)'), transparent: true, opacity: 0.9, depthWrite: false, blending: THREE.AdditiveBlending }));
  glow.scale.setScalar(1.8);
  mesh.add(glow);
  this.scene.add(mesh);
  const speed = 11;
  this.projectiles.push({ mesh, vel: new THREE.Vector3(Math.sin(angle) * speed, 0, Math.cos(angle) * speed), life: 3.4, damage: 13, hit: false });
}

updateProjectiles(dt, player) {
  for (let i = this.projectiles.length - 1; i >= 0; i--) {
    const p = this.projectiles[i];
    p.life -= dt;
    p.mesh.position.addScaledVector(p.vel, dt);
    p.mesh.rotation.y += dt * 8;
    const dx = p.mesh.position.x - player.pos.x;
    const dz = p.mesh.position.z - player.pos.z;
    if (!p.hit && Math.hypot(dx, dz) < 0.75 && Math.abs(p.mesh.position.y - (player.pos.y + 1.1)) < 1.4) {
      p.hit = true;
      if (!(player.state === 'roll' && player.invuln > 0)) player.takeDamage(p.damage, p.mesh.position, { unblockable: true });
      this.effects.burst(p.mesh.position, { color: 0xa9eaff, count: 16, speed: 4, size: 0.1, gravity: 2, life: 0.5 });
    }
    if (p.life <= 0 || p.hit || Math.hypot(p.mesh.position.x, p.mesh.position.z) > 26) {
      this.scene.remove(p.mesh);
      p.mesh.geometry.dispose();
      p.mesh.material.dispose();
      this.projectiles.splice(i, 1);
    }
  }
}

spawnShockwave(pos, maxRadius, damage, color) {
  const geo = new THREE.RingGeometry(0.93, 1, 64);
  const mat = new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.85, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.set(pos.x, 0.45, pos.z);
  mesh.rotation.x = -Math.PI / 2;
  mesh.scale.setScalar(0.6);
  this.scene.add(mesh);
  this.hazards.push({ type: 'wave', mesh, radius: 0.6, maxRadius, speed: 13, damage, hit: false, life: 1.3, color });
}

castEruption(player) {
  this.audio.cast();
  for (let i = 0; i < 2; i++) {
    const offset = i === 0 ? 0 : rand(-3, 3);
    const pos = new THREE.Vector3(player.pos.x + offset, 0.42, player.pos.z + (i === 0 ? 0 : rand(-3, 3)));
    const geo = new THREE.CircleGeometry(2.6, 32);
    const mat = new THREE.MeshBasicMaterial({ color: 0xff4f1e, transparent: true, opacity: 0.18, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending });
    const mesh = new THREE.Mesh(geo, mat);
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.copy(pos);
    this.scene.add(mesh);
    const ring = new THREE.Mesh(new THREE.RingGeometry(2.5, 2.7, 48), new THREE.MeshBasicMaterial({ color: 0xffa45e, transparent: true, opacity: 0.7, side: THREE.DoubleSide, depthWrite: false, blending: THREE.AdditiveBlending }));
    ring.rotation.x = -Math.PI / 2;

      ring.rotation.x = -Math.PI / 2;
      ring.position.copy(pos);
      this.scene.add(ring);
      this.hazards.push({ type: 'eruption', mesh, ring, pos, timer: 0.95, radius: 2.7, damage: 34, exploded: false, life: 1.6 });
    }
  }

  updateHazards(dt, player) {
    for (let i = this.hazards.length - 1; i >= 0; i--) {
      const h = this.hazards[i];
      h.life -= dt;
      if (h.type === 'wave') {
        h.radius += h.speed * dt;
        h.mesh.scale.setScalar(h.radius);
        h.mesh.material.opacity = clamp(1 - h.radius / h.maxRadius, 0, 1) * 0.85;
        const d = this.distanceTo(player.pos);
        if (!h.hit && Math.abs(d - h.radius) < 0.8 && player.invuln <= 0) {
          h.hit = true;
          player.takeDamage(h.damage, this.pos, { unblockable: true });
          this.effects.burst(new THREE.Vector3(player.pos.x, 0.6, player.pos.z), { color: h.color, count: 24, speed: 4, size: 0.12, gravity: 5 });
        }
        if (h.radius >= h.maxRadius || h.life <= 0) {
          this.scene.remove(h.mesh);
          h.mesh.geometry.dispose();
          h.mesh.material.dispose();
          this.hazards.splice(i, 1);
        }
      } else if (h.type === 'eruption') {
        h.timer -= dt;
        const p = clamp(1 - h.timer / 0.95, 0, 1);
        h.mesh.material.opacity = 0.12 + p * 0.22 + Math.sin(this.game.time * 20) * 0.05;
        h.mesh.scale.setScalar(0.5 + p * 0.5);
        if (!h.exploded && h.timer <= 0) {
          h.exploded = true;
          h.mesh.material.opacity = 0.7;
          this.effects.flash(h.pos, { color: 0xff6a22, size: 6, life: 0.6, y: 0.5 });
          this.effects.ring(h.pos, { color: 0xff6a22, radius: h.radius + 1, life: 0.6 });
          this.effects.burst(new THREE.Vector3(h.pos.x, 0.6, h.pos.z), { color: 0xff7a2e, count: 60, speed: 9, size: 0.15, gravity: 5, life: 1.1 });
          this.audio.hit(true);
          if (Math.hypot(player.pos.x - h.pos.x, player.pos.z - h.pos.z) < h.radius && player.invuln <= 0) {
            player.takeDamage(h.damage, h.pos, { unblockable: true });
          }
          h.mesh.material.opacity = 0.35;
        }
        if (h.life <= 0) {
          this.scene.remove(h.mesh);
          this.scene.remove(h.ring);
          h.mesh.geometry.dispose();
          h.mesh.material.dispose();
          h.ring.geometry.dispose();
          h.ring.material.dispose();
          this.hazards.splice(i, 1);
        }
      }
    }
  }

  teleportBehind(player) {
    const forward = new THREE.Vector3(Math.sin(player.yaw), 0, Math.cos(player.yaw));
    this.pos.set(player.pos.x - forward.x * 3.2, 0.36, player.pos.z - forward.z * 3.2);
    this.yaw = Math.atan2(player.pos.x - this.pos.x, player.pos.z - this.pos.z);
    this.blink = 1;
  }

  enterPhaseTwo() {
    this.phase = 2;
    this.state = 'phase';
    this.stateTime = 0;
    this.attack = null;
    this.weaponGlow = 1;
    this.audio.roar(true);
    this.game.bossPhaseTwo(this);
    this.effects.ring(this.pos, { color: 0xff5b22, radius: 10, life: 1.2 });
    this.effects.flash(new THREE.Vector3(this.pos.x, 2.4, this.pos.z), { color: 0xff6b30, size: 8, life: 0.8 });
    this.effects.burst(new THREE.Vector3(this.pos.x, 1.2, this.pos.z), { color: 0xff5b22, count: 100, speed: 11, size: 0.18, gravity: 2, life: 1.6 });
    this.game.cameraShake(0.8);
  }

  takeDamage(amount, poise = 0, player = null, kind = 'light') {
    if (!this.alive) return;
    this.hp = Math.max(0, this.hp - amount);
    this.hitFlash = 1;
    this.staggerMeter += poise;
    this.game.updateBossUI(this);
    if (kind === 'riposte') {
      this.staggerTimer = Math.max(this.staggerTimer, 1.2);
      this.staggerMeter = 0;
    }
    if (this.hp <= 0) {
      this.die();
      return;
    }
    if (this.staggerMeter >= 100 && this.state !== 'stagger' && this.state !== 'phase') {
      this.stagger();
    }
  }

  stagger() {
    this.state = 'stagger';
    this.stateTime = 0;
    this.staggerTimer = 2.55;
    this.staggerMeter = 0;
    this.attack = null;
    this.parryCue = false;
    this.weaponGlow = 0;
    this.audio.roar(false);
    this.effects.ring(this.pos, { color: 0xffe0a0, radius: 6, life: 0.8 });
    this.effects.burst(new THREE.Vector3(this.pos.x, 2.1, this.pos.z), { color: 0xffe0a0, count: 45, speed: 7, size: 0.13, gravity: 3 });
    this.game.bossStaggered(this);
    this.game.cameraShake(0.35);
  }

  die() {
    if (this.defeated) return;
    this.defeated = true;
    this.state = 'dead';
    this.stateTime = 0;
    this.deadTime = 0;
    this.attack = null;
    this.parryCue = false;
    this.audio.bossDeath();
    this.effects.flash(new THREE.Vector3(this.pos.x, 2.2, this.pos.z), { color: this.config.color, size: 9, life: 0.9 });
    this.effects.ring(this.pos, { color: this.config.color, radius: 12, life: 1.3 });
    this.effects.burst(new THREE.Vector3(this.pos.x, 2.0, this.pos.z), { color: this.config.color, count: 120, speed: 10, size: 0.16, gravity: 2, life: 1.8 });
    this.game.cameraShake(0.9);
    this.game.bossDefeated(this);
  }

  animate(dt, player) {
    const t = this.game.time;
    this.walkPhase += dt * (this.state === 'approach' ? 8 : 2.2);
    const ph = this.walkPhase;
    const bob = Math.sin(t * 1.8) * 0.012;

    this.body.position.set(0, 0, 0);
    this.body.rotation.set(0, 0, 0);
    this.model.position.y = 0;
    this.torso.position.y = 1.86 + bob;
    this.torso.rotation.set(0, 0, 0);
    this.head.rotation.set(0, 0, 0);
    this.armR.rotation.set(-0.18, 0, 0.18);
    this.armL.rotation.set(-0.12, 0, -0.18);
    this.elbowR.rotation.set(0.12, 0, 0);
    this.elbowL.rotation.set(0.12, 0, 0);
    this.cape.rotation.set(0.08, 0, 0);
    this.capePivot.rotation.set(0, 0, 0);
    if (this.legR) this.legR.rotation.set(0, 0, 0);
    if (this.legL) this.legL.rotation.set(0, 0, 0);
    if (this.weapon) this.weapon.rotation.set(0, 0, 0);
    if (this.weaponL) this.weaponL.rotation.set(0, 0, 0);
    if (this.halo) this.halo.position.y = 1.5 + Math.sin(t * 1.2) * 0.05;

    if (this.state === 'approach' || this.state === 'idle') {
      const moving = this.state === 'approach';
      const amp = moving ? 1 : 0.12;
      if (this.legR) {
        this.legR.rotation.x = Math.sin(ph) * 0.48 * amp;
        this.legL.rotation.x = -Math.sin(ph) * 0.48 * amp;
      }
      this.armR.rotation.x = -0.18 - Math.sin(ph) * 0.2 * amp;
      this.armL.rotation.x = -0.12 + Math.sin(ph) * 0.2 * amp;
      this.torso.rotation.z = Math.sin(ph * 2) * 0.025 * amp;
      this.cape.rotation.x = 0.08 + (moving ? 0.16 : 0.02) + Math.sin(t * 1.4) * 0.03;
      this.model.position.y = moving ? Math.abs(Math.sin(ph)) * 0.03 : 0;
    }

    if (this.state === 'windup' && this.attack) {
      const a = this.attack;
      const p = clamp(this.stateTime / a.windup, 0, 1);
      const e = p * p * (3 - 2 * p);
      if (a.kind === 'slam') {
        this.armR.rotation.x = lerp(-0.2, -2.9, e);
        this.armR.rotation.z = lerp(0.18, 0.55, e);
        this.elbowR.rotation.x = lerp(0.12, 0.6, e);
        this.torso.rotation.x = lerp(0, -0.16, e);
        this.torso.rotation.y = lerp(0, -0.25, e);
        this.armL.rotation.x = lerp(-0.12, -0.9, e);
        this.cape.rotation.x = 0.1 + e * 0.3;
      } else if (a.kind === 'fan' || a.kind === 'eruption') {
        this.armR.rotation.x = lerp(-0.2, -2.6, e);
        this.armL.rotation.x = lerp(-0.12, -2.6, e);
        this.armR.rotation.z = lerp(0.18, 0.45, e);
        this.armL.rotation.z = lerp(-0.18, -0.45, e);
        this.torso.rotation.x = lerp(0, -0.12, e);
        this.head.rotation.x = lerp(0, -0.2, e);
      } else if (a.kind === 'charge') {
        this.armR.rotation.x = lerp(-0.2, -1.2, e);
        this.armR.rotation.z = lerp(0.18, 0.6, e);
        this.torso.rotation.x = lerp(0, 0.25, e);
        this.body.position.y = -e * 0.18;
        if (this.legR) { this.legR.rotation.x = 0.4 * e; this.legL.rotation.x = -0.5 * e; }
      } else if (a.kind === 'twin') {
        this.armR.rotation.x = lerp(-0.2, -1.9, e);
        this.armL.rotation.x = lerp(-0.12, -1.7, e);
        this.armR.rotation.z = lerp(0.18, 0.7, e);
        this.armL.rotation.z = lerp(-0.18, -0.7, e);
        this.torso.rotation.y = lerp(0, -0.55, e);
      } else {
        this.armR.rotation.x = lerp(-0.2, -2.45, e);
        this.armR.rotation.z = lerp(0.18, 0.7, e);
        this.elbowR.rotation.x = lerp(0.12, 0.4, e);
        this.torso.rotation.y = lerp(0, -0.75, e);
        this.torso.rotation.x = lerp(0, 0.12, e);
        this.armL.rotation.x = lerp(-0.12, -0.7, e);
        this.cape.rotation.x = 0.1 + e * 0.25;
      }
      this.head.rotation.y = -this.torso.rotation.y * 0.4;
    } else if (this.state === 'active' && this.attack) {
      const a = this.attack;
      const p = clamp(this.stateTime / a.active, 0, 1);
      const e = 1 - Math.pow(1 - p, 2);
      if (a.kind === 'slam') {
        this.armR.rotation.x = lerp(-2.9, 1.15, e);
        this.armR.rotation.z = lerp(0.55, -0.1, e);
        this.torso.rotation.x = lerp(-0.16, 0.55, e);
        this.torso.rotation.y = lerp(-0.25, 0.3, e);
        this.body.position.y = -Math.sin(p * Math.PI) * 0.12;
      } else if (a.kind === 'fan' || a.kind === 'eruption') {
        this.armR.rotation.x = lerp(-2.6, -0.2, e);
        this.armL.rotation.x = lerp(-2.6, -0.2, e);
        this.torso.rotation.x = lerp(-0.12, 0.18, e);
      } else if (a.kind === 'twin') {
        this.armR.rotation.x = lerp(-1.9, 0.7, e);
        this.armL.rotation.x = lerp(-1.7, 0.4, e);
        this.torso.rotation.y = lerp(-0.55, 0.65, e);
      } else if (a.kind === 'flurry') {
        const s = Math.sin(p * Math.PI * 3);
        this.armR.rotation.x = -1.4 + s * 1.9;
        this.armL.rotation.x = -1.3 - s * 1.6;
        this.torso.rotation.y = s * 0.7;
        this.torso.rotation.x = 0.2;
      } else if (a.kind === 'charge') {
        this.armR.rotation.x = -1.0;
        this.armR.rotation.z = 0.8;
        this.torso.rotation.x = 0.35;
        this.body.position.y = -0.1;
      } else {
        this.armR.rotation.x = lerp(-2.45, 0.85, e);
        this.armR.rotation.z = lerp(0.7, -0.15, e);
        this.torso.rotation.y = lerp(-0.75, 0.72, e);
        this.torso.rotation.x = lerp(0.12, 0.38, e);
        this.armL.rotation.x = lerp(-0.7, -0.15, e);
        this.cape.rotation.x = 0.3 + e * 0.3;
      }
      if (this.legR) this.legR.rotation.x = -0.25 * e;
      if (this.legL) this.legL.rotation.x = 0.3 * e;
    } else if (this.state === 'recovery') {
      const p = clamp(this.stateTime / this.attack.recovery, 0, 1);
      const e = 1 - p;
      this.armR.rotation.x = -0.2 - e * 0.8;
      this.torso.rotation.x = e * 0.2;
      this.torso.rotation.y = e * 0.15;
    } else if (this.state === 'stagger') {
      const p = Math.sin(clamp(this.stateTime / 0.45, 0, 1) * Math.PI / 2);
      this.body.position.y = -0.28 * p;
      this.torso.rotation.x = 0.55 * p;
      this.torso.rotation.z = -0.12 * p;
      this.head.rotation.x = 0.4 * p;
      this.armR.rotation.x = 0.35 * p;
      this.armL.rotation.x = 0.3 * p;
      this.armR.rotation.z = 0.45 * p;
      this.armL.rotation.z = -0.45 * p;
      if (this.legR) { this.legR.rotation.x = -0.4 * p; this.legL.rotation.x = -0.5 * p; }
      this.cape.rotation.x = 0.05;
    } else if (this.state === 'phase') {
      const p = Math.sin(clamp(this.stateTime / 2.1, 0, 1) * Math.PI);
      this.torso.rotation.x = -0.3 * p;
      this.head.rotation.x = -0.5 * p;
      this.armR.rotation.x = -2.4 * p;
      this.armL.rotation.x = -2.4 * p;
      this.armR.rotation.z = 0.6 * p;
      this.armL.rotation.z = -0.6 * p;
      this.body.position.y = 0.08 * p;
      this.cape.rotation.x = 0.5 * p;
      if (this.legR) { this.legR.rotation.x = -0.2 * p; this.legL.rotation.x = -0.2 * p; }
    } else if (this.state === 'dead') {
      const p = clamp(this.deadTime / 1.7, 0, 1);
      const e = p * p * (3 - 2 * p);
      this.body.rotation.z = e * 1.35;
      this.body.rotation.x = e * 0.25;
      this.body.position.y = -e * 0.45;
      this.armR.rotation.x = -0.8 * e;
      this.armL.rotation.x = -0.6 * e;
      this.armR.rotation.z = 0.5 * e;
      this.armL.rotation.z = -0.5 * e;
      if (this.legR) { this.legR.rotation.x = 0.2 * e; this.legL.rotation.x = -0.2 * e; }
      this.cape.rotation.x = 0.6 * e;
      this.model.position.y = -e * 0.1;
    }

    if (this.blink > 0) {
      this.blink = Math.max(0, this.blink - dt * 3);
      this.model.visible = this.blink < 0.65;
    } else if (this.state !== 'dead') {
      this.model.visible = true;
    }

    if (this.state === 'dead') {
      this.model.visible = this.deadTime < 3.6;
      this.root.position.y = 0.36;
    }
  }
}

