@import '@fontsource/cinzel/400.css';
@import '@fontsource/cinzel/600.css';
@import '@fontsource/cinzel/700.css';
@import '@fontsource/cinzel/900.css';
@import '@fontsource/eb-garamond/400.css';
@import '@fontsource/eb-garamond/500.css';
@import '@fontsource/eb-garamond/600.css';
@import '@fontsource/eb-garamond/400-italic.css';

:root {
  --ink: #050608;
  --ink-soft: #0b0d11;
  --bone: #e8e0cf;
  --bone-dim: #a49c8c;
  --gold: #c3a46b;
  --gold-bright: #f1d69a;
  --gold-dark: #6f5834;
  --blood: #8f2029;
  --blood-bright: #d24a4a;
  --stamina: #7d9c72;
  --glass: rgba(8, 10, 14, 0.68);
  --line: rgba(195, 164, 107, 0.32);
  --line-soft: rgba(195, 164, 107, 0.15);
  --shadow: 0 30px 80px rgba(0, 0, 0, 0.65);
  --serif: 'Cinzel', 'Times New Roman', serif;
  --body: 'EB Garamond', Georgia, serif;
}

* { box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: var(--ink);
  color: var(--bone);
  font-family: var(--body);
  -webkit-font-smoothing: antialiased;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

button { font: inherit; color: inherit; }
button:focus-visible { outline: 1px solid var(--gold-bright); outline-offset: 5px; }

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: #050608;
}

.scene-fx { position: fixed; inset: 0; pointer-events: none; z-index: 2; }
.grain {
  position: absolute; inset: -50%;
  opacity: 0.05;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
  animation: grainShift 0.7s steps(3) infinite;
}
@keyframes grainShift {
  0% { transform: translate3d(0, 0, 0); }
  33% { transform: translate3d(-2%, 1.4%, 0); }
  66% { transform: translate3d(1.5%, -1%, 0); }
  100% { transform: translate3d(0, 0, 0); }
}
.vignette {
  position: absolute; inset: 0;
  background:
    radial-gradient(ellipse at 50% 47%, transparent 28%, rgba(0, 0, 0, 0.28) 72%, rgba(0, 0, 0, 0.72) 100%),
    linear-gradient(to bottom, rgba(0, 0, 0, 0.32), transparent 20%, transparent 74%, rgba(0, 0, 0, 0.55));
}
#damageFlash, #parryFlash {
  position: absolute; inset: 0; opacity: 0;
  transition: opacity 0.25s ease-out;
}
#damageFlash { background: radial-gradient(ellipse at center, transparent 35%, rgba(130, 8, 16, 0.7) 100%); box-shadow: inset 0 0 180px rgba(160, 10, 20, 0.55); }
#parryFlash { background: radial-gradient(circle at 50% 55%, rgba(255, 242, 205, 0.3), transparent 52%); }
#damageFlash.hit { opacity: 1; transition-duration: 0.04s; }
#parryFlash.hit { opacity: 1; transition-duration: 0.04s; }

.boot {
  position: fixed; inset: 0; z-index: 100;
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 18px; background: #050608;
  transition: opacity 1s ease, visibility 1s;
}
.boot.is-done { opacity: 0; visibility: hidden; }
.boot p {
  margin: 0; font-family: var(--serif); font-size: 11px; letter-spacing: 0.45em;
  text-transform: uppercase; color: var(--bone-dim);
}
.boot-mark {
  width: 46px; height: 46px; border: 1px solid var(--line);
  transform: rotate(45deg); position: relative;
  animation: bootPulse 2s ease-in-out infinite;
}
.boot-mark::before, .boot-mark::after {
  content: ''; position: absolute; inset: 9px; border: 1px solid var(--gold-dark);
}
.boot-mark::after { inset: 18px; background: var(--gold); border: 0; }
.boot-line { width: 180px; height: 1px; background: rgba(255, 255, 255, 0.09); overflow: hidden; }
.boot-line i { display: block; width: 50%; height: 100%; background: var(--gold); animation: bootLine 1.6s ease-in-out infinite; }
@keyframes bootLine { from { transform: translateX(-110%); } to { transform: translateX(220%); } }
@keyframes bootPulse { 50% { transform: rotate(45deg) scale(1.08); box-shadow: 0 0 40px rgba(195, 164, 107, 0.18); } }

/* ============ MENU ============ */
.screen {
  position: fixed; inset: 0; z-index: 20;
  display: none;
}
.screen.is-active { display: flex; }
.menu-screen { align-items: stretch; }
.menu-shade {
