  background: linear-gradient(100deg, transparent, rgba(241, 214, 154, 0.18), transparent);
  transition: transform 0.7s ease;
}
.primary-btn:hover { border-color: var(--gold-bright); color: #fff8e8; box-shadow: 0 0 55px rgba(195, 164, 107, 0.16), inset 0 0 30px rgba(195, 164, 107, 0.06); transform: translateY(-1px); }
.primary-btn:hover::before { transform: translateX(101%); }
.primary-btn .btn-key { font-family: var(--body); font-size: 18px; letter-spacing: 0; color: var(--gold); border-left: 1px solid var(--line); padding-left: 18px; }
.menu-note { margin: 18px 0 0; font-family: var(--serif); font-size: 8px; letter-spacing: 0.25em; color: rgba(232, 224, 207, 0.3); text-transform: uppercase; }

.menu-aside {
  align-self: center; justify-self: end; width: min(100%, 400px);
  padding: 28px 28px 24px; background: linear-gradient(155deg, rgba(13, 15, 20, 0.7), rgba(5, 6, 9, 0.5));
  border: 1px solid var(--line-soft); backdrop-filter: blur(12px);
  animation: riseIn 1.2s 0.15s cubic-bezier(.2,.7,.2,1) both;
  box-shadow: var(--shadow);
}
.aside-title { margin: 0 0 22px; font-family: var(--serif); font-size: 9px; letter-spacing: 0.36em; color: var(--gold); }
.boss-list { list-style: none; margin: 0 0 24px; padding: 0; border-top: 1px solid var(--line-soft); }
.boss-list li {
  display: grid; grid-template-columns: 38px 1fr 14px; align-items: center; gap: 12px;
  padding: 14px 0; border-bottom: 1px solid var(--line-soft); opacity: 0.58;
  transition: opacity 0.3s, padding-left 0.3s;
}
.boss-list li.is-current { opacity: 1; padding-left: 4px; }
.boss-list .numeral { font-family: var(--serif); font-size: 17px; color: var(--gold-dark); }
.boss-list li.is-current .numeral { color: var(--gold); }
.boss-list b { display: block; font-family: var(--serif); font-size: 10px; font-weight: 600; letter-spacing: 0.18em; color: var(--bone); }
.boss-list small { display: block; margin-top: 4px; font-size: 13px; color: var(--bone-dim); letter-spacing: 0.03em; }
.seal { width: 8px; height: 8px; border: 1px solid var(--line); transform: rotate(45deg); }
.is-current .seal { background: var(--gold); border-color: var(--gold); box-shadow: 0 0 12px rgba(195, 164, 107, 0.45); }
.parry-card { display: flex; gap: 14px; padding: 14px 0 20px; border-bottom: 1px solid var(--line-soft); }
.parry-icon { flex: 0 0 32px; height: 32px; border: 1px solid var(--line); transform: rotate(45deg); display: grid; place-items: center; margin-top: 3px; }
.parry-icon span { width: 9px; height: 9px; border: 1px solid var(--gold); transform: rotate(45deg); }
.parry-card b { display: block; font-family: var(--serif); font-size: 9px; letter-spacing: 0.25em; color: var(--gold); margin-bottom: 6px; }
.parry-card p { margin: 0; font-size: 14px; line-height: 1.35; color: rgba(232, 224, 207, 0.55); }
.menu-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 9px 16px; padding-top: 18px; }
.menu-controls span { display: flex; align-items: center; gap: 9px; font-family: var(--serif); font-size: 7px; letter-spacing: 0.16em; color: var(--bone-dim); }
kbd { font-family: var(--serif); font-size: 8px; letter-spacing: 0.12em; padding: 3px 5px; border: 1px solid var(--line-soft); color: var(--gold); background: rgba(195, 164, 107, 0.04); }
.menu-controls em { font-style: normal; }
@keyframes riseIn { from { opacity: 0; transform: translateY(26px); } to { opacity: 1; transform: translateY(0); } }

/* ============ HUD ============ */
.hud { position: fixed; inset: 0; z-index: 10; pointer-events: none; opacity: 1; transition: opacity 0.45s; }
.hud.is-hidden { opacity: 0; }
.hud-top {
  position: absolute; top: 0; left: 0; right: 0;
  display: flex; justify-content: space-between; align-items: flex-start;
  padding: max(20px, env(safe-area-inset-top)) clamp(18px, 3vw, 46px) 0;
}
.act-badge { display: flex; flex-direction: column; gap: 5px; padding-top: 3px; }
.act-kicker { font-family: var(--serif); font-size: 8px; letter-spacing: 0.34em; color: var(--gold); }
.act-kicker b { font-weight: 600; color: var(--gold-bright); }
.act-name { font-family: var(--serif); font-size: 8px; letter-spacing: 0.28em; color: rgba(232, 224, 207, 0.38); }
.run-readout { display: flex; gap: clamp(18px, 2.5vw, 40px); text-align: right; padding-top: 2px; }
.run-readout > div { display: flex; flex-direction: column; gap: 3px; }
.readout-label { font-family: var(--serif); font-size: 7px; letter-spacing: 0.3em; color: rgba(232, 224, 207, 0.32); }
.run-readout b { font-family: var(--serif); font-size: 15px; font-weight: 400; letter-spacing: 0.12em; color: rgba(232, 224, 207, 0.74); }

.boss-plate {
  position: absolute; left: 50%; top: max(22px, env(safe-area-inset-top)); transform: translateX(-50%);
  width: min(46vw, 620px); opacity: 0; transition: opacity 0.6s;
}
.boss-plate.is-active { opacity: 1; }
.boss-heading { text-align: center; margin-bottom: 8px; }
.boss-epithet { display: block; font-family: var(--serif); font-size: 7px; letter-spacing: 0.34em; color: rgba(232, 224, 207, 0.38); margin-bottom: 4px; }
.boss-name { display: block; font-family: var(--serif); font-size: clamp(11px, 1.2vw, 15px); font-weight: 600; letter-spacing: 0.24em; color: #eee6d4; text-shadow: 0 2px 20px #000; }
.boss-bar { position: relative; height: 7px; background: rgba(0, 0, 0, 0.65); border-top: 1px solid rgba(195, 164, 107, 0.22); border-bottom: 1px solid rgba(195, 164, 107, 0.22); }
.boss-bar::before, .boss-bar::after {
  content: ''; position: absolute; top: 50%; width: 7px; height: 7px; border: 1px solid var(--gold-dark);
  transform: translateY(-50%) rotate(45deg); background: var(--ink);
}
.boss-bar::before { left: -13px; }
.boss-bar::after { right: -13px; }
.boss-hp, .boss-hp-ghost { position: absolute; inset: 0; transform-origin: left center; }
.boss-hp { background: linear-gradient(180deg, #c53b3b, #7d141d 55%, #4c0a10); box-shadow: 0 0 18px rgba(180, 40, 40, 0.25); transition: transform 0.15s linear; }
.boss-hp-ghost { background: rgba(232, 224, 207, 0.55); transition: transform 0.8s cubic-bezier(.2,.7,.2,1); }
.boss-bar-ornament { position: absolute; left: 50%; top: -3px; width: 1px; height: 13px; background: var(--gold-dark); }
.boss-meta { display: flex; justify-content: space-between; padding-top: 6px; font-family: var(--serif); font-size: 7px; letter-spacing: 0.24em; color: rgba(232, 224, 207, 0.35); }
.boss-stagger { color: var(--gold-bright); opacity: 0; transition: opacity 0.2s; }
.boss-stagger.is-on { opacity: 1; animation: staggerBlink 0.6s steps(2) infinite; }
@keyframes staggerBlink { 50% { opacity: 0.3; } }

.reticle { position: absolute; left: 50%; top: 50%; width: 22px; height: 22px; transform: translate(-50%, -50%); opacity: 0.35; transition: opacity 0.25s; }
.reticle::before, .reticle::after { content: ''; position: absolute; background: var(--bone); }
.reticle::before { left: 50%; top: 0; width: 1px; height: 7px; box-shadow: 0 15px 0 var(--bone); transform: translateX(-50%); }
.reticle::after { top: 50%; left: 0; height: 1px; width: 7px; box-shadow: 15px 0 0 var(--bone); transform: translateY(-50%); }
.reticle i { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; transform: translate(-50%, -50%) rotate(45deg); background: var(--gold); }
.reticle.is-target { opacity: 0.8; }
.reticle.is-target::before, .reticle.is-target::after { background: var(--gold-bright); box-shadow: none; }
.reticle.is-target i { background: var(--blood-bright); }

.reticle.is-target i { background: var(--blood-bright); }

.parry-prompt {
  position: absolute; left: 50%; top: 59%; transform: translate(-50%, -50%) scale(0.92);
  display: flex; flex-direction: column; align-items: center; gap: 4px;
  opacity: 0; transition: opacity 0.1s, transform 0.14s;
}
.parry-prompt.is-active { opacity: 1; transform: translate(-50%, -50%) scale(1); }
.parry-prompt > span { font-family: var(--serif); font-size: 12px; font-weight: 700; letter-spacing: 0.4em; color: #fff8e6; text-shadow: 0 0 20px rgba(255, 235, 180, 0.8); padding-left: 0.4em; }
.parry-prompt small { font-family: var(--serif); font-size: 6px; letter-spacing: 0.24em; color: rgba(255, 248, 230, 0.55); }
.parry-ring { position: absolute; top: -19px; width: 94px; height: 94px; }
.parry-ring svg { width: 100%; height: 100%; transform: rotate(-90deg); }
.parry-ring circle { fill: none; stroke: rgba(255, 244, 210, 0.85); stroke-width: 1.5; stroke-dasharray: 276; stroke-dashoffset: 0; filter: drop-shadow(0 0 5px rgba(255, 230, 170, 0.6)); }
.parry-prompt.is-active .parry-ring circle { animation: parryRing 0.42s linear forwards; }
@keyframes parryRing { from { stroke-dashoffset: 0; } to { stroke-dashoffset: 276; } }

.toast {
  position: absolute; left: 50%; top: 33%; transform: translate(-50%, 8px);
  font-family: var(--serif); font-size: clamp(13px, 1.5vw, 18px); letter-spacing: 0.3em;
  color: var(--gold-bright); text-shadow: 0 0 30px rgba(195, 164, 107, 0.45), 0 3px 20px #000;
  opacity: 0; transition: opacity 0.25s, transform 0.35s; white-space: nowrap;
}
.toast.is-on { opacity: 1; transform: translate(-50%, 0); }
.toast.is-danger { color: #ffb3a9; text-shadow: 0 0 30px rgba(180, 20, 30, 0.6), 0 3px 20px #000; }

.combo { position: absolute; right: clamp(24px, 4vw, 64px); top: 41%; display: flex; align-items: baseline; gap: 7px; opacity: 0; transform: translateX(12px); transition: opacity 0.2s, transform 0.25s; }
.combo.is-on { opacity: 1; transform: translateX(0); }
.combo b { font-family: var(--serif); font-size: 42px; font-weight: 400; line-height: 1; color: var(--gold-bright); text-shadow: 0 0 24px rgba(195, 164, 107, 0.3); }
.combo span { font-family: var(--serif); font-size: 7px; letter-spacing: 0.25em; color: var(--bone-dim); }

.hud-bottom {
  position: absolute; left: 0; right: 0; bottom: 0;
  display: flex; align-items: flex-end; justify-content: space-between;
  padding: 0 clamp(18px, 3vw, 46px) max(22px, env(safe-area-inset-bottom));
}
.player-panel { display: flex; align-items: flex-end; gap: 14px; }
.player-sigil { width: 42px; height: 42px; border: 1px solid var(--line); transform: rotate(45deg); display: grid; place-items: center; margin-bottom: 4px; background: rgba(5, 6, 8, 0.45); }
.player-sigil span { width: 16px; height: 16px; border: 1px solid var(--gold-dark); }
.player-sigil.low { border-color: var(--blood); animation: sigilPulse 1s ease-in-out infinite; }
@keyframes sigilPulse { 50% { box-shadow: 0 0 24px rgba(180, 20, 30, 0.5); } }
.bars { width: min(33vw, 350px); }
.bar-row { display: grid; grid-template-columns: 58px 1fr 31px; align-items: center; gap: 9px; margin-bottom: 5px; }
.bar-label { font-family: var(--serif); font-size: 6px; letter-spacing: 0.24em; color: rgba(232, 224, 207, 0.38); }
.bar-track { height: 6px; background: rgba(0, 0, 0, 0.58); border: 1px solid rgba(232, 224, 207, 0.1); position: relative; }
.bar-fill, .bar-ghost { position: absolute; inset: 0; transform-origin: left center; }
.bar-ghost { background: rgba(232, 224, 207, 0.4); transition: transform 0.9s cubic-bezier(.2,.7,.2,1); }
.hp { background: linear-gradient(180deg, #b6343b, #74131a); box-shadow: 0 0 14px rgba(160, 25, 35, 0.3); transition: transform 0.15s linear; }
.stamina { background: linear-gradient(180deg, #91a879, #4d6748); transition: transform 0.08s linear; }
.stamina.is-low { background: linear-gradient(180deg, #a8805e, #6f4b34); }
.bar-row b { font-family: var(--serif); font-size: 9px; font-weight: 400; text-align: right; color: rgba(232, 224, 207, 0.7); }
.stamina-row { grid-template-columns: 58px 1fr 31px; }
.stamina-row .bar-track { grid-column: 2 / 4; }
.stamina-row .bar-label { grid-row: 1; }
.flask-row { display: flex; align-items: center; gap: 9px; margin-top: 10px; }
.flask-label { font-family: var(--serif); font-size: 6px; letter-spacing: 0.2em; color: rgba(232, 224, 207, 0.3); }
.flasks { display: flex; gap: 5px; }
.flask { width: 9px; height: 15px; border: 1px solid rgba(195, 164, 107, 0.4); background: rgba(195, 164, 107, 0.05); border-radius: 1px 1px 3px 3px; transform: skew(-4deg); }
.flask.full { background: linear-gradient(180deg, #e7b76a, #8f5423); box-shadow: 0 0 8px rgba(225, 156, 65, 0.3); }
.flask-key { font-family: var(--serif); font-size: 6px; color: var(--gold-dark); border: 1px solid var(--line-soft); padding: 1px 4px; }
.control-hints { display: flex; gap: 18px; align-items: center; padding-bottom: 5px; }
.control-hints span { font-family: var(--serif); font-size: 6px; letter-spacing: 0.14em; color: rgba(232, 224, 207, 0.3); white-space: nowrap; }
.control-hints kbd { margin-right: 4px; }

.lock-badge {
  position: absolute; left: 50%; bottom: 18%; transform: translateX(-50%);
  font-family: var(--serif); font-size: 7px; letter-spacing: 0.28em; color: var(--gold);
  opacity: 0; transition: opacity 0.2s;
}
.lock-badge.is-on { opacity: 0.8; }
.lock-badge i { display: inline-block; width: 5px; height: 5px; border: 1px solid var(--gold); transform: rotate(45deg); margin-right: 5px; }
.boss-offscreen { position: absolute; left: 50%; top: 16%; transform: translateX(-50%); opacity: 0; }
.boss-offscreen.is-on { opacity: 0.7; }
.boss-offscreen i { display: block; width: 10px; height: 10px; border-top: 1px solid var(--blood-bright); border-left: 1px solid var(--blood-bright); transform: rotate(45deg); animation: offscreenBob 1s ease-in-out infinite; }
@keyframes offscreenBob { 50% { transform: rotate(45deg) translate(2px, 2px); } }

/* ============ OVERLAYS ============ */
.overlay {
  position: fixed; inset: 0; z-index: 30; display: flex; flex-direction: column;
  align-items: center; justify-content: center; text-align: center;
  opacity: 0; visibility: hidden; transition: opacity 0.7s ease, visibility 0.7s;
  background: radial-gradient(ellipse at center, rgba(5, 6, 8, 0.25), rgba(5, 6, 8, 0.86));
}
.overlay.is-active { opacity: 1; visibility: visible; }
.boss-intro { background: radial-gradient(ellipse at center, rgba(5, 6, 8, 0.12), rgba(5, 6, 8, 0.7)); pointer-events: none; }
.intro-rule { width: 1px; height: 54px; background: linear-gradient(to bottom, transparent, var(--gold)); margin-bottom: 25px; }
.intro-rule.small { height: 34px; background: linear-gradient(to bottom, var(--gold-dark), transparent); margin: 26px 0 0; }
.intro-act { margin: 0 0 16px; font-family: var(--serif); font-size: 10px; letter-spacing: 0.55em; color: var(--gold); }
.boss-intro h2 { margin: 0; font-family: var(--serif); font-size: clamp(32px, 5vw, 72px); font-weight: 600; letter-spacing: 0.16em; color: #efe7d4; text-shadow: 0 0 70px rgba(0, 0, 0, 0.9); }
.intro-epithet { margin: 14px 0 0; font-family: var(--body); font-style: italic; font-size: clamp(14px, 1.4vw, 19px); letter-spacing: 0.12em; color: rgba(232, 224, 207, 0.55); }
.boss-intro.is-active .intro-rule { animation: introLine 1.2s ease both; }
.boss-intro.is-active h2 { animation: introTitle 1.2s 0.1s cubic-bezier(.2,.7,.2,1) both; }
.boss-intro.is-active .intro-epithet, .boss-intro.is-active .intro-act { animation: fadeUp 1s 0.35s ease both; }
@keyframes introLine { from { transform: scaleY(0); } to { transform: scaleY(1); } }
@keyframes introTitle { from { opacity: 0; letter-spacing: 0.32em; filter: blur(6px); } to { opacity: 1; letter-spacing: 0.16em; filter: blur(0); } }
@keyframes fadeUp { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }

.result-screen { background: radial-gradient(ellipse at center, rgba(5, 6, 8, 0.55), rgba(5, 6, 8, 0.95)); }
.result-kicker { margin: 0 0 14px; font-family: var(--serif); font-size: 9px; letter-spacing: 0.44em; color: rgba(232, 224, 207, 0.42); }
.result-screen h2 { margin: 0; font-family: var(--serif); font-size: clamp(54px, 8vw, 116px); font-weight: 600; letter-spacing: 0.08em; line-height: 1; color: #e7ddca; }
.death-screen h2 { color: #9b252d; text-shadow: 0 0 80px rgba(140, 10, 20, 0.45); }
.death-screen.is-active h2 { animation: deathReveal 1.4s cubic-bezier(.2,.7,.2,1) both; }
@keyframes deathReveal { from { opacity: 0; letter-spacing: 0.3em; filter: blur(10px); } to { opacity: 1; letter-spacing: 0.08em; filter: blur(0); } }
.victory-screen h2 { color: var(--gold-bright); text-shadow: 0 0 90px rgba(195, 164, 107, 0.35); }
.result-copy { margin: 20px 0 34px; font-size: 17px; font-style: italic; letter-spacing: 0.04em; color: rgba(232, 224, 207, 0.52); }
.result-actions { display: flex; align-items: center; gap: 24px; }
.ghost-btn { padding: 15px 8px; border: 0; border-bottom: 1px solid var(--line); background: transparent; cursor: pointer; font-family: var(--serif); font-size: 8px; letter-spacing: 0.3em; color: var(--bone-dim); transition: color 0.2s, border-color 0.2s; }
.ghost-btn:hover { color: var(--bone); border-color: var(--gold); }
.victory-stats { display: flex; gap: clamp(22px, 4vw, 58px); margin: 4px 0 40px; }
.victory-stats div { display: flex; flex-direction: column; gap: 8px; }
.victory-stats span { font-family: var(--serif); font-size: 7px; letter-spacing: 0.28em; color: var(--bone-dim); }
.victory-stats b { font-family: var(--serif); font-size: 25px; font-weight: 400; color: var(--gold); }
.pause-screen { background: rgba(5, 6, 8, 0.82); backdrop-filter: blur(9px); }
.pause-screen h2 { font-size: clamp(44px, 6vw, 80px); }
.pause-hint { margin-top: 35px; font-family: var(--serif); font-size: 7px; letter-spacing: 0.2em; color: rgba(232, 224, 207, 0.26); }

/* ============ TOUCH ============ */
.touch-controls { display: none; position: fixed; inset: 0; z-index: 15; pointer-events: none; }
body.playing.touch .touch-controls { display: block; }
.joystick {
  position: absolute; left: max(22px, env(safe-area-inset-left)); bottom: max(28px, env(safe-area-inset-bottom));
  width: 124px; height: 124px; border-radius: 50%; border: 1px solid rgba(195, 164, 107, 0.22);
  background: radial-gradient(circle, rgba(195, 164, 107, 0.05), rgba(5, 6, 8, 0.25));
  pointer-events: auto; touch-action: none;
}
.joystick::before { content: ''; position: absolute; inset: 24px; border: 1px solid rgba(195, 164, 107, 0.1); border-radius: 50%; }
.joystick-knob { position: absolute; left: 50%; top: 50%; width: 44px; height: 44px; margin: -22px 0 0 -22px; border-radius: 50%; border: 1px solid rgba(232, 224, 207, 0.38); background: rgba(195, 164, 107, 0.14); box-shadow: 0 0 20px rgba(0, 0, 0, 0.4); }
.touch-right { position: absolute; right: max(18px, env(safe-area-inset-right)); bottom: max(22px, env(safe-area-inset-bottom)); width: 206px; height: 190px; pointer-events: none; }
.touch-btn {
  position: absolute; pointer-events: auto; touch-action: none;
  width: 62px; height: 62px; border-radius: 50%; border: 1px solid rgba(195, 164, 107, 0.32);
  background: rgba(8, 10, 14, 0.55); backdrop-filter: blur(5px);
  color: var(--bone); display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 1px;
  transition: transform 0.08s, background 0.08s, border-color 0.08s;
}
.touch-btn b { font-family: var(--serif); font-size: 7px; font-weight: 600; letter-spacing: 0.12em; }
.touch-btn small { font-family: var(--body); font-size: 10px; color: var(--gold-dark); }
.touch-btn:active, .touch-btn.is-down { transform: scale(0.92); background: rgba(195, 164, 107, 0.22); border-color: var(--gold-bright); }
.attack-btn { right: 0; bottom: 0; width: 72px; height: 72px; border-color: rgba(195, 164, 107, 0.5); }
.heavy-btn { right: 68px; bottom: 52px; width: 54px; height: 54px; }
.dodge-btn { right: 2px; bottom: 80px; width: 56px; height: 56px; }
.parry-btn { right: 74px; bottom: 0; width: 58px; height: 58px; border-color: rgba(232, 224, 207, 0.45); }
.parry-btn b { color: #fff1ce; }
.lock-btn { right: 130px; bottom: 112px; width: 46px; height: 46px; }
.flask-btn { right: 14px; bottom: 145px; width: 46px; height: 46px; }
.camera-zone { position: absolute; right: 0; top: 0; width: 55%; height: 65%; pointer-events: auto; touch-action: none; }
.rotate-notice { display: none; position: fixed; inset: 0; z-index: 80; background: #050608; flex-direction: column; align-items: center; justify-content: center; text-align: center; }
.rotate-notice span { font-family: var(--serif); font-size: 11px; letter-spacing: 0.4em; color: var(--gold); }
.rotate-notice p { font-size: 16px; color: var(--bone-dim); }

/* ============ RESPONSIVE ============ */
@media (max-width: 1080px) {
  .menu-main { grid-template-columns: 1fr 320px; gap: 3vw; }
  .menu-aside { padding: 22px; }
  .title-block h1 { font-size: clamp(64px, 11vw, 130px); }
  .control-hints span:nth-child(n+4) { display: none; }
}

@media (max-width: 820px) {
  .menu-frame { padding: 20px 22px 16px; }
  .menu-topline span:last-child, .menu-footer span:last-child { display: none; }
  .menu-main { grid-template-columns: 1fr; align-content: center; gap: 24px; }
  .menu-aside { display: none; }
  .title-block h1 { font-size: clamp(64px, 19vw, 120px); margin-bottom: 18px; }
  .lede { font-size: 16px; margin-bottom: 24px; }
  .primary-btn { min-width: 0; width: min(100%, 320px); }
  .menu-note { max-width: 280px; line-height: 1.6; }
  .menu-footer { padding-top: 12px; }

  .hud-top { padding: max(12px, env(safe-area-inset-top)) 14px 0; }
  .act-badge { display: none; }
  .run-readout { gap: 14px; }
  .run-readout b { font-size: 12px; }
  .boss-plate { top: max(14px, env(safe-area-inset-top)); width: min(72vw, 480px); }
  .boss-epithet { font-size: 6px; }
  .boss-name { font-size: 10px; letter-spacing: 0.16em; }
  .boss-meta { font-size: 6px; }
