const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');

(async () => {
  const browser = await chromium.launch({ headless: false, args: ['--disable-gpu'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', e => { console.log('PAGEERROR', e.message); errors.push(e.message); });
  page.on('console', m => { if (m.type() === 'error' && !m.text().includes('404')) console.log('CONSOLE', m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(1400);
  await page.evaluate(() => document.getElementById('startBtn').click());
  await page.waitForTimeout(250);
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.composer.render = () => {};
    g.clock.getDelta = () => 1 / 60;
  });
  await page.waitForTimeout(1200);

  const state = () => page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return {
      game: g.state, time: +g.time.toFixed(2), parries: g.parryCount,
      player: { state: g.player.state, hp: g.player.hp, stamina: +g.player.stamina.toFixed(1), invuln: +g.player.invuln.toFixed(2) },
      boss: { state: g.boss.state, attack: g.boss.attack?.id, hp: g.boss.hp, phase: g.boss.phase, stagger: +g.boss.staggerMeter.toFixed(0), cue: g.boss.parryCue },
      toast: g.ui.toast.textContent,
    };
  });

  // Set up a controlled parryable attack.
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.player.pos.set(0, 0.36, 0.4);
    g.player.state = 'idle'; g.player.stateTime = 0; g.player.invuln = 0; g.player.hp = 100;
    g.boss.pos.set(0, 0.36, -3.0);
    g.boss.hp = g.boss.maxHp;
    g.boss.state = 'idle'; g.boss.think = 0; g.boss.cooldown = 0; g.boss.staggerMeter = 0;
  });
  let cueState = null;
  for (let i = 0; i < 200; i++) {
    const s = await state();
    if (s.boss.cue) { cueState = s; break; }
    await page.waitForTimeout(20);
  }
  console.log('CUE', cueState);
  await page.keyboard.press('KeyF');
  await page.waitForFunction(() => window.__ASHEN_VOW__.boss.state === 'stagger', null, { timeout: 1500 }).catch(() => {});
  console.log('PARRY_RESULT', await state());

  // Riposte.
  await page.keyboard.press('KeyJ');
  await page.waitForTimeout(900);
  console.log('RIPOSTE_RESULT', await state());

  // Force slam and parry it directly.
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.boss.state = 'idle'; g.boss.stateTime = 0; g.boss.think = 0; g.boss.cooldown = 0; g.boss.staggerMeter = 0; g.boss.attack = null;
    g.boss.pos.set(0, 0.36, -2.4);
    g.player.pos.set(0, 0.36, 0.4); g.player.state = 'idle'; g.player.stateTime = 0; g.player.invuln = 0; g.player.hp = 100;
    g.boss.beginAttack(g.boss.config.attacks.find(a => a.kind === 'slam'));
  });
  for (let i = 0; i < 200; i++) {
    const s = await state();
    if (s.boss.cue) { console.log('SLAM_CUE', s); break; }
    await page.waitForTimeout(20);
  }
  await page.keyboard.press('KeyF');
  await page.waitForFunction(() => window.__ASHEN_VOW__.boss.state === 'stagger', null, { timeout: 1500 }).catch(() => {});
  console.log('SLAM_PARRY', await state());

  // Ensure normal slam still hurts when not parried.
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.boss.state = 'idle'; g.boss.stateTime = 0; g.boss.staggerMeter = 0; g.boss.attack = null;
    g.boss.pos.set(0, 0.36, -2.4);
    g.player.pos.set(0, 0.36, 0.4); g.player.state = 'idle'; g.player.stateTime = 0; g.player.invuln = 0; g.player.hp = 100;
    g.boss.beginAttack(g.boss.config.attacks.find(a => a.kind === 'slam'));
  });
  await page.waitForTimeout(1300);
  console.log('SLAM_HIT', await state());

  // King phase transition.
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.spawnBoss('king');
    g.boss.spawnAt({ x: 0, y: 0.36, z: -2.4, clone() { return this; }, copy() {} });
    g.boss.think = 999;
    g.state = 'playing';
    g.player.reset(); g.player.pos.set(0, 0.36, 0.4);
    g.boss.pos.set(0, 0.36, -2.4);
    g.boss.hp = g.boss.maxHp * 0.49;
  });
  await page.waitForTimeout(300);
