@media (max-width: 900px) {
  body.playing .touch-controls { display: block; }
}

input.newString:
@media (max-width: 900px) {
  body.playing .touch-controls { display: block; }
}

/* Touch landscape: clear a lane between the joystick and the action cluster. */
@media (pointer: coarse) and (orientation: landscape) {
  .hud-bottom {
    left: 158px;
    right: 238px;
    bottom: max(12px, env(safe-area-inset-bottom));
    padding: 0;
    justify-content: flex-start;
  }
  .player-panel { width: 100%; }
  .player-sigil { display: none; }
  .bars { width: 100%; max-width: 430px; }
  .control-hints { display: none; }
}

