  this.attackTime = 0;
  this.hitIndex = 0;
  this.attackHit = false;
  this.parryCue = false;
  this.weaponGlow = 0;
  this.windupSound = false;
  this.blinked = false;
  this.game.bossTelegraph(this, attack);
  this.audio.whoosh();
}

