const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const path = '/home/runner/work/PlayGround/PlayGround/screenshots';
(async () => {
  const browser = await chromium.launch({ headless: false, args: ['--disable-gpu'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => { console.log('PAGEERROR', e.message); errors.push(e.message); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(1800);
  await page.evaluate(() => document.getElementById('startBtn').click());
  await page.waitForTimeout(250);
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g._real = g.composer.render.bind(g.composer);
    g.composer.render = () => {};
    g.clock.getDelta = () => 1 / 60;
    g.player.pos.set(0, 0.36, 2.4);
    g.boss.pos.set(0, 0.36, -2.2);
    g.player.state = 'idle';
    g.player.stateTime = 0;
    g.player.hp = 100;
    g.player.invuln = 0;
    g.boss.state = 'idle';
    g.boss.think = 0;
    g.boss.cooldown = 0;
    g.boss.attack = null;
  });
  let cue = null;
  for (let i = 0; i < 500; i++) {
    const s = await page.evaluate(() => {
      const g = window.__ASHEN_VOW__;
      return { cue: g.boss.parryCue, state: g.boss.state, attack: g.boss.attack?.id };
    });
    if (s.cue) { cue = s; break; }
    await page.waitForTimeout(12);
  }
  console.log('CUE', cue);
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.clock.getDelta = () => 0;
    g.composer.render = g._real;
  });
  await page.waitForTimeout(2400);
  console.log('PROMPT', await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    const el = g.ui.parryPrompt;
    const r = el.getBoundingClientRect();
    return {
      className: el.className,
      left: el.style.left,
      top: el.style.top,
      rect: { x: +r.x.toFixed(0), y: +r.y.toFixed(0), w: +r.width.toFixed(0), h: +r.height.toFixed(0) },
      bossState: g.boss.state,
      cue: g.boss.parryCue,
      tipVisible: g.boss.weaponTipGlow.material.opacity,
    };
  }));
  await page.screenshot({ path: `${path}/parry.png` });
  await browser.close();
})();

