const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
const sleep = (ms) => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await chromium.launch({ headless: false, args: ['--disable-gpu'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', e => { console.log('PAGEERROR', e.message); errors.push(e.message); });
  page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(1500);
  await page.evaluate(() => document.getElementById('startBtn').click());
  await page.waitForTimeout(300);
  // Fast-forward game logic, skip expensive rendering.
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.composer.render = () => {};
    g.clock.getDelta = () => 1 / 60;
  });
  await page.waitForTimeout(2500);
  console.log('START', await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return { state: g.state, time: +g.time.toFixed(2), boss: g.boss.state, bossDist: +g.player.distanceToBoss(g.boss).toFixed(2), bossPos: g.boss.pos.toArray(), hp: g.player.hp };
  }));

  // Move player into melee range and face the boss.
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.player.pos.set(0, 0.36, 0.4);
    g.boss.pos.set(0, 0.36, -3.0);
    g.boss.think = 0.05;
    g.boss.cooldown = 0;
    g.boss.state = 'idle';
    g.boss.stateTime = 0;
  });

  // Wait for a parryable windup, then parry when the cue shows.
  let parried = false;
  for (let i = 0; i < 120; i++) {
    const s = await page.evaluate(() => {
      const g = window.__ASHEN_VOW__;
      return { cue: g.boss.parryCue, state: g.boss.state, attack: g.boss.attack?.id, ptime: +g.boss.stateTime.toFixed(2), pstate: g.player.state, ptime2: +g.player.stateTime.toFixed(2) };
    });
    if (s.cue && s.state === 'windup') {
      console.log('CUE', s);
      await page.keyboard.press('KeyF');
      await page.waitForTimeout(80);
      console.log('AFTER_PARRY', await page.evaluate(() => {
        const g = window.__ASHEN_VOW__;
        return { parryCount: g.parryCount, playerState: g.player.state, bossState: g.boss.state, bossHp: g.boss.hp, toast: g.ui.toast.textContent };
      }));
      parried = true;
      break;
    }
    await page.waitForTimeout(25);
  }
  if (!parried) console.log('NO CUE OBSERVED');

  // Riposte while staggered.
  if (parried) {
    await page.keyboard.press('KeyJ');
    await page.waitForTimeout(900);
    console.log('RIPOSTE', await page.evaluate(() => {
      const g = window.__ASHEN_VOW__;
      return { bossHp: g.boss.hp, bossState: g.boss.state, playerState: g.player.state, toast: g.ui.toast.textContent };
    }));
  }

  // Basic light attack from range.
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.player.pos.set(0, 0.36, 0.4);
    g.boss.pos.set(0, 0.36, -2.8);
    g.boss.state = 'idle'; g.boss.think = 999; g.boss.cooldown = 999; g.boss.staggerTimer = 0;
    g.player.state = 'idle'; g.player.stateTime = 0; g.player.stamina = 100; g.player.yaw = Math.PI;
  });
  const hpBefore = await page.evaluate(() => window.__ASHEN_VOW__.boss.hp);
  await page.keyboard.press('KeyJ');
  await page.waitForTimeout(500);
  console.log('ATTACK', await page.evaluate((hpBefore) => {
    const g = window.__ASHEN_VOW__;
    return { hpBefore, hpAfter: g.boss.hp, playerState: g.player.state, stamina: +g.player.stamina.toFixed(1), combo: g.player.combo };
  }, hpBefore));

  // Dodge.
  await page.keyboard.press('ShiftLeft');
  await page.waitForTimeout(80);
  console.log('DODGE', await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return { state: g.player.state, invuln: +g.player.invuln.toFixed(2), stamina: +g.player.stamina.toFixed(1) };
  }));

  // Defeat first boss -> transition into chorister.
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.boss.hp = 1;
    g.player.pos.set(0, 0.36, 0.4);
    g.boss.pos.set(0, 0.36, -2.8);
    g.player.state = 'idle'; g.player.yaw = Math.PI; g.boss.state = 'idle'; g.boss.think = 999;
  });
  await page.keyboard.press('KeyJ');
  await page.waitForTimeout(500);
  console.log('DEFEAT', await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return { gameState: g.state, bossState: g.boss.state, bossHp: g.boss.hp, toast: g.ui.toast.textContent };
  }));
  await page.waitForTimeout(3600);
  console.log('NEXT', await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return { gameState: g.state, act: g.act, bossKind: g.bossKind, bossName: g.boss.name, intro: g.ui.intro.className, bossHp: g.boss.hp };
  }));
  await page.waitForTimeout(2200);
  console.log('ACT2_PLAY', await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return { gameState: g.state, bossKind: g.bossKind, bossState: g.boss.state };
  }));

  // Death + retry.
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.player.invuln = 0;
    g.player.takeDamage(999, { x: 0, y: 0, z: 0 });
  });
  await page.waitForTimeout(1800);
  console.log('DEATH', await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return { gameState: g.state, overlay: g.ui.death.className, hp: g.player.hp, deaths: g.deaths };
  }));
  await page.click('#retryBtn');
  await page.waitForTimeout(1000);
  console.log('RETRY', await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return { gameState: g.state, hp: g.player.hp, bossHp: g.boss.hp, bossKind: g.bossKind, intro: g.ui.intro.className };
  }));

  // Jump to king and victory.
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.spawnBoss('king');
    g.boss.spawnAt({ x: 0, y: 0.36, z: -2.8, clone() { return this; }, copy() {} });
    g.boss.think = 999;
    g.state = 'playing';
    g.ui.intro.classList.remove('is-active');
    g.player.reset();
    g.player.pos.set(0, 0.36, 0.4);
    g.boss.pos.set(0, 0.36, -2.8);
  });
  await page.evaluate(() => { const g = window.__ASHEN_VOW__; g.boss.hp = 1; g.boss.takeDamage(10, 0, g.player, 'heavy'); });
  await page.waitForTimeout(3400);
  await page.waitForTimeout(400);
  console.log('VICTORY', await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return { gameState: g.state, overlay: g.ui.victory.className, rank: g.ui.finalRank.textContent, time: g.ui.finalTime.textContent, best: localStorage.getItem('ashen-vow-best') };
  }));

  console.log('ERRORS', errors);
  await browser.close();
})();

