const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright');
(async () => {
  const browser = await chromium.launch({ headless: false, args: ['--disable-gpu'] });
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
  const errors = [];
  page.on('pageerror', e => { console.log('PAGEERROR', e.message); errors.push(e.message); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(1400);
  await page.evaluate(() => document.getElementById('startBtn').click());
  await page.waitForTimeout(250);
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.composer.render = () => {};
    g.clock.getDelta = () => 1 / 60;
  });
  await page.waitForTimeout(700);

  async function setup(kind) {
    await page.evaluate((kind) => {
      const g = window.__ASHEN_VOW__;
      g.player.pos.set(0, 0.36, 0.4);
      g.boss.pos.set(0, 0.36, -2.4);
      g.player.reset();
      g.player.pos.set(0, 0.36, 0.4);
      g.player.yaw = Math.PI;
      g.player.state = 'idle';
      g.player.stateTime = 0;
      g.player.hp = 100;
      g.player.invuln = 0;
      g.boss.state = 'idle';
      g.boss.stateTime = 0;
      g.boss.staggerTimer = 0;
      g.boss.staggerMeter = 0;
      g.boss.attack = null;
      g.boss.hazards.forEach(h => h.life = 0);
      g.boss.beginAttack(g.boss.config.attacks.find(a => a.kind === kind));
    }, kind);
  }

  async function parryAtCue(label) {
    for (let i = 0; i < 200; i++) {
      const cue = await page.evaluate(() => window.__ASHEN_VOW__.boss.parryCue);
      if (cue) break;
      await page.waitForTimeout(10);
    }
    const before = await page.evaluate(() => {
      const g = window.__ASHEN_VOW__;
      return { cue: g.boss.parryCue, attack: g.boss.attack?.id, bossState: g.boss.state, hp: g.player.hp, hazards: g.boss.hazards.length, prompt: g.ui.parryPrompt.className };
    });
    await page.keyboard.press('KeyF');
    await page.waitForTimeout(450);
    const after = await page.evaluate(() => {
      const g = window.__ASHEN_VOW__;
      return {
        parryCount: g.parryCount, playerState: g.player.state, playerHp: g.player.hp,
        bossState: g.boss.state, bossHp: g.boss.hp, hazards: g.boss.hazards.length,
        toast: g.ui.toast.textContent, prompt: g.ui.parryPrompt.className,
      };
    });
    console.log(label, { before, after });
  }

  await setup('cleave');
  await parryAtCue('CLEAVE_PARRY');
  await page.waitForTimeout(120);
  await page.keyboard.press('KeyJ');
  await page.waitForTimeout(700);
  console.log('RIPOSTE', await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return { bossHp: g.boss.hp, bossState: g.boss.state, playerState: g.player.state, toast: g.ui.toast.textContent };
  }));

  await page.waitForTimeout(800);
  await setup('slam');
  await parryAtCue('SLAM_PARRY');
  await page.waitForTimeout(250);
  console.log('SLAM_SETTLE', await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return { playerHp: g.player.hp, bossState: g.boss.state, hazards: g.boss.hazards.length, parryCount: g.parryCount };
  }));

  console.log('ERRORS', errors);
  await browser.close();
})();

