    screen: { width: 390, height: 844 },
    deviceScaleFactor: 2,
    isMobile: true,
    hasTouch: true,
    userAgent: 'Mozilla/5.0 (Linux; Android 13; Pixel 7) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120 Mobile Safari/537.36',
  });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', e => { console.log('PAGEERROR', e.message); errors.push(e.message); });

  // Start game
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.waitForTimeout(2000);
  await page.tap('#startBtn');
  await page.waitForTimeout(1200);

  // Wait for parry cue to appear
  console.log('Searching for parry cue...');
  for (let i = 0; i < 400; i++) {
    const cue = await page.evaluate(() => window.__ASHEN_VOW__.boss.parryCue);
    if (cue) {
      console.log('Found parry cue at iteration', i);
      break;
    }
    await page.waitForTimeout(10);
  }

  // Test touch pause button
  console.log('Testing touch pause button...');
  await page.tap('#pauseTouchBtn');
  await page.waitForTimeout(500);
  const paused = await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    return { state: g.state, pauseActive: g.ui.pause.classList.contains('is-active') };
  });
  console.log('Paused state:', paused);

  if (paused.pauseActive) {
    console.log('Pause button working correctly');
    await page.tap('#resumeBtn');
    await page.waitForTimeout(600);
    const resumed = await page.evaluate(() => {
      const g = window.__ASHEN_VOW__;
      return { state: g.state, pauseActive: g.ui.pause.classList.contains('is-active') };
    });
    console.log('Resumed state:', resumed);
  } else {
    console.log('ERROR: Touch pause button not working!');
  }

  // Take screenshot
  await page.screenshot({ path: `${path}/mobile-pause-test.png` });

  // Test dynamic parry prompt positioning
  console.log('Testing dynamic parry prompt positioning...');
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g._real = g.composer.render.bind(g.composer);
    g.composer.render = () => {};
    g.clock.getDelta = () => 1 / 60;
  });
  await page.waitForTimeout(1200);

  // Position for parry cue test
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.player.pos.set(0, 0.36, 0.4);
    g.boss.pos.set(0, 0.36, -2.2);
    g.player.reset();
    g.player.yaw = Math.PI;
    g.boss.state = 'idle';
    g.boss.think = 999;
    g.boss.cooldown = 0;
  });

  // Wait for parry cue
  let parried = false;
  for (let i = 0; i < 300; i++) {
    const cue = await page.evaluate(() => window.__ASHEN_VOW__.boss.parryCue);
    if (cue) {
      parried = true;
      console.log('Found parry cue at iteration', i);
      break;
    }
    await page.waitForTimeout(12);
  }

  if (parried) {
    await page.keyboard.press('KeyF');
    await page.waitForTimeout(500);
  } else {
    console.log('WARNING: Could not trigger parry cue for positioning test');
  }

  // Check prompt position
  await page.evaluate(() => {
    const g = window.__ASHEN_VOW__;
    g.clock.getDelta = () => 0;
    g.composer.render = g._real;
  });
  await page.waitForTimeout(2200);
  console.log('Parry prompt position check:', await page.evaluate(() => {
    const el = window.__ASHEN_VOW__.ui.parryPrompt;
    const r = el.getBoundingClientRect();
    return { left: el.style.left, top: el.style.top, rect: { x: +r.x.toFixed(0), y: +r.y.toFixed(0), w: +r.width.toFixed(0), h: +r.height.toFixed(0) } };
  }));

  await page.screenshot({ path: `${path}/mobile-parry-positioning.png` });

  console.log('ERRORS', errors);
  await browser.close();
})();

